/* =============================== ERRORS ================================ */

function fail_(code, message, data) {
  const e = new Error(message);
  e.appCode = code;
  e.isAppError = true;
  if (data) e.appData = data;
  throw e;
}

/* ============================ TEXT UTILITIES =========================== */

function cleanVal(v) {
  if (v === null || v === undefined) return "";
  return String(v).trim();
}

function normalizeArabic(text) {
  if (text === null || text === undefined) return "";
  let s = String(text);
  s = s.replace(/[\u064B-\u065F\u0670\u0640]/g, "");          // diacritics + tatweel
  s = s.replace(/[\u200E\u200F\u202A-\u202E\u2066-\u2069]/g, ""); // bidi marks
  s = s.replace(/[\u00A0\u2007\u202F]/g, " ");
  s = s.replace(/[إأآا]/g, "ا").replace(/ة/g, "ه").replace(/ى/g, "ي");
  s = s.replace(/\s+/g, " ").trim().toLowerCase();
  return s;
}

function normName(s) { return normalizeArabic(s); }

function normHeader(h) {
  return normalizeArabic(String(h === null || h === undefined ? "" : h).replace(/[\r\n]+/g, " "));
}

/** Canonical form of a course code: "أحمد 1", "أحمد - 1", "أحمد-1" => "احمد-1" */
function normCode(c) {
  let s = normalizeArabic(c);
  s = s.replace(/\s*[-_–—]+\s*/g, "-").replace(/\s+/g, "-");
  return s;
}

/** Split a student's code cell ("نصري-4, أسامة-2") into [{raw,norm}] */
function parseCodes(str) {
  const out = [];
  String(str === null || str === undefined ? "" : str).split(/[,،;\r\n\/]+/).forEach(function (p) {
    const t = p.trim();
    if (t) out.push({ raw: t, norm: normCode(t) });
  });
  return out;
}

function isUnassignedNorm(norm) {
  return norm.indexOf(CFG.UNASSIGNED_PREFIX) === 0;
}

/** "ايمان-ع-3" => {prefix:"ايمان-ع", num:3} ; "بلعلجيه1-1" => {prefix:"بلعلجيه1", num:1} */
function splitCode(norm) {
  const m = /^(.*)-(\d+)$/.exec(norm);
  return m ? { prefix: m[1], num: parseInt(m[2], 10) } : null;
}

const TIER_RANK = { T1: 1, T2: 2, T3: 3, T4: 4 };

/** Single role parser used everywhere. */
function parseTier(raw) {
  const up = String(raw === null || raw === undefined ? "" : raw).toUpperCase();
  const n = normalizeArabic(raw);
  if (up.indexOf("T4") !== -1 || n.indexOf("مدير عام") !== -1 || up.indexOf("DIRECTOR") !== -1 || up.indexOf("ADMIN") !== -1) return "T4";
  if (up.indexOf("T3") !== -1 || n.indexOf("مشرف عام") !== -1 || n.indexOf("مدير") !== -1 || up.indexOf("MANAGER") !== -1) return "T3";
  if (up.indexOf("T2") !== -1 || n.indexOf("مشرف") !== -1 || up.indexOf("SUPERVISOR") !== -1) return "T2";
  return "T1";
}

/** Free text coming from the client: strip control chars, collapse spaces, limit length. */
/** Canonical age-group label. The old "36+" (also typed "+36") now means "60+". */
function normAge_(v) {
  const s = cleanVal(v).replace(/\s+/g, "");
  if (/^\+?36\+?$/.test(s) || /^\+60$/.test(s)) return "60+";
  return s;
}

function text_(v, max, label, required) {
  let s = cleanVal(v).replace(/[\u0000-\u001F\u007F]/g, " ").replace(/\s+/g, " ").trim();
  if (required && !s) fail_("BAD_INPUT", label + " مطلوب.");
  if (s.length > max) fail_("BAD_INPUT", label + " طويل جداً.");
  if (s && /^[=+@]|^-(?=[^\d\s])/.test(s)) fail_("BAD_INPUT", label + " يحتوي على قيمة غير صالحة.");
  return s;
}

function tz_() { return Session.getScriptTimeZone(); }

function fmtDate_(d, pattern) { return Utilities.formatDate(d, tz_(), pattern); }

/** Cell (Date | string) -> "yyyy-MM-dd" or "" */
function toISODate_(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? "" : fmtDate_(v, "yyyy-MM-dd");
  const s = cleanVal(v);
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s);
  if (m) return m[1] + "-" + ("0" + m[2]).slice(-2) + "-" + ("0" + m[3]).slice(-2);
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s);
  if (m) return m[3] + "-" + ("0" + m[2]).slice(-2) + "-" + ("0" + m[1]).slice(-2);
  return "";
}

function isoWeek_(iso) {
  const p = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
  const day = dt.getUTCDay() || 7;
  dt.setUTCDate(dt.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(dt.getUTCFullYear(), 0, 1));
  return Math.ceil(((dt - yearStart) / 86400000 + 1) / 7);
}

function validISODate_(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const p = s.split("-").map(Number);
  const d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
  return d.getUTCFullYear() === p[0] && d.getUTCMonth() === p[1] - 1 && d.getUTCDate() === p[2];
}

function formatTiming_(display, raw) {
  const disp = cleanVal(display);
  if (disp) {
    const m = disp.match(/(\d{1,2}):(\d{2})/);
    return m ? ("0" + m[1]).slice(-2) + ":" + m[2] : disp;
  }
  if (raw instanceof Date) return fmtDate_(raw, "HH:mm");
  return cleanVal(raw);
}

/* ============================ SHEET ACCESS ============================= */

function openSS_() { return SpreadsheetApp.openById(SPREADSHEET_ID); }

/** Exact (then whitespace/diacritics-insensitive exact) sheet lookup. NEVER partial. */
function findSheet_(ss, names) {
  for (let i = 0; i < names.length; i++) {
    const s = ss.getSheetByName(names[i]);
    if (s) return s;
  }
  const all = ss.getSheets();
  const wanted = names.map(function (n) { return normalizeArabic(n).replace(/\s+/g, ""); });
  for (let j = 0; j < all.length; j++) {
    const nm = normalizeArabic(all[j].getName()).replace(/\s+/g, "");
    if (wanted.indexOf(nm) !== -1) return all[j];
  }
  return null;
}

function findCol_(headers, spec) {
  const ex = (spec.h || []).map(normHeader);
  for (let i = 0; i < headers.length; i++) {
    if (headers[i] !== "" && ex.indexOf(headers[i]) !== -1) return i;
  }
  const st = (spec.s || []).map(normHeader);
  for (let k = 0; k < headers.length; k++) {
    for (let q = 0; q < st.length; q++) {
      if (headers[k].indexOf(st[q]) === 0) return k;
    }
  }
  return -1;
}

/**
 * Reads a whole table (header = row 1). Throws a clear Arabic error if a REQUIRED
 * column is missing — there are no silent hard-coded fallbacks any more.
 */
function readTable_(ss, key, withDisplay) {
  const def = SCHEMAS[key];
  const sheet = findSheet_(ss, SHEET_NAMES[def.sheet]);
  if (!sheet) fail_("SHEET_MISSING", "الجدول «" + SHEET_NAMES[def.sheet][0] + "» غير موجود في قاعدة البيانات.");
  const range = sheet.getDataRange();
  const values = range.getValues();
  const display = withDisplay ? range.getDisplayValues() : null;
  const headers = (values[0] || []).map(normHeader);
  const idx = {};
  const missing = [];
  Object.keys(def.cols).forEach(function (f) {
    const i = findCol_(headers, def.cols[f]);
    idx[f] = i;
    if (i === -1 && def.cols[f].req) missing.push((def.cols[f].h || def.cols[f].s)[0]);
  });
  if (missing.length) fail_("SCHEMA", "أعمدة مفقودة في الجدول «" + sheet.getName() + "»: " + missing.join("، "));
  return { key: key, sheet: sheet, values: values, display: display, idx: idx };
}

/** Last row (1-based) having a non-empty value in ANY of the given 1-based columns. */
function lastDataRow_(sheet, cols1) {
  const n = sheet.getMaxRows();
  let last = 1;
  cols1.forEach(function (c) {
    const vals = sheet.getRange(1, c, n, 1).getValues();
    for (let i = vals.length - 1; i >= 1; i--) {
      if (cleanVal(vals[i][0]) !== "") { if (i + 1 > last) last = i + 1; break; }
    }
  });
  return last;
}

function ensureRows_(sheet, lastNeededRow) {
  const max = sheet.getMaxRows();
  if (lastNeededRow > max) sheet.insertRowsAfter(max, lastNeededRow - max);
}

/* =========================== DOMAIN LOADERS ============================ */

function splitSupervisors_(raw) {
  if (!raw) return [];
  return raw.split(/[,،;\/\r\n]+/).map(function (s) { return s.trim(); }).filter(Boolean).map(function (s) {
    return s.indexOf("@") !== -1 ? s.toLowerCase() : normName(s);
  });
}

/** «الصفة» may hold two symbols for one person: T1-T4 (التعليم) and/or A1-A4 (البرامج), e.g. "T3, A2". */
function actTierOf_(raw) {
  const m = String(raw === null || raw === undefined ? "" : raw).toUpperCase().match(/(^|[^A-Z0-9])A([1-4])(?![0-9])/g);
  if (!m) return "";
  let best = 0;
  m.forEach(function (x) { const n = parseInt(x.slice(-1), 10); if (n > best) best = n; });
  return best ? "A" + best : "";
}
/** the person also carries the A2 symbol (A3 + A2 together: the highest tier decides the screens, A2 adds «متابعة مجلس الصف») */
function actHasA2_(act) { return !!act && (act.tier === "A2" || /(^|[^A-Z0-9])A2(?![0-9])/.test(String(act.roleRaw || "").toUpperCase())); }
/** the same request seen as a plain A2: only HIS classes (no group scope, no supervisees) */
function actClassCtx_(ctx) { return Object.assign({}, ctx, { act: Object.assign({}, ctx.act, { tier: "A2" }) }); }
/** T5 = المدير التنفيذي: read-only overview of both departments (never a التعليم teacher) */
function ceoOf_(raw) { return /(^|[^A-Z0-9])T5(?![0-9])/.test(String(raw === null || raw === undefined ? "" : raw).toUpperCase()); }
/** M1 = مجالس الذكر: creates «طلبات مجالس الذكر» (الأنشطة only; never a التعليم role) */
function majlisOf_(raw) { return /(^|[^A-Z0-9])M1(?![0-9])/.test(String(raw === null || raw === undefined ? "" : raw).toUpperCase()); }
/** false only for a row that has a البرامج symbol (or T5 / M1) and no التعليم role at all */
function hasEduRole_(raw) {
  if (ceoOf_(raw) && !/(^|[^A-Z0-9])T[1-4](?![0-9])/.test(String(raw).toUpperCase())) return false;
  if (!actTierOf_(raw) && !majlisOf_(raw)) return true;
  const up = String(raw).toUpperCase();
  return /(^|[^A-Z0-9])T[1-4](?![0-9])/.test(up) || /ADMIN|MANAGER|SUPERVISOR|DIRECTOR/.test(up) || normalizeArabic(raw).indexOf("مشرف") !== -1 || normalizeArabic(raw).indexOf("مدير") !== -1;
}

function loadStaff_(tbl, everyone) {
  const v = tbl.values, ix = tbl.idx, staff = [];
  for (let i = 1; i < v.length; i++) {
    const r = v[i];
    const name = cleanVal(r[ix.name]);
    const email = cleanVal(r[ix.email]).toLowerCase();
    if (!name && !email) continue;
    const prefix = cleanVal(r[ix.prefix]);
    const roleRaw = cleanVal(r[ix.role]);
    if (!everyone && !hasEduRole_(roleRaw)) continue;   // programs-only person: not part of التعليم
    const tier = parseTier(roleRaw);
    const supRaw = ix.supervisor !== -1 ? cleanVal(r[ix.supervisor]) : "";
    staff.push({
      row: i + 1,
      name: name,
      normName: normName(name),
      email: email,
      prefix: prefix,
      normPrefix: prefix ? normCode(prefix) : "",
      roleRaw: roleRaw,
      tier: tier,
      rank: TIER_RANK[tier],
      supervisorRaw: supRaw,
      supervisors: splitSupervisors_(supRaw),
      location: ix.location !== -1 ? cleanVal(r[ix.location]) : "",
      pinHash: ix.pinHash !== -1 ? cleanVal(r[ix.pinHash]) : "",
      actTier: actTierOf_(roleRaw),
      ceo: ceoOf_(roleRaw),
      majlis: majlisOf_(roleRaw),
      actTokens: ix.actScope !== -1 ? cleanVal(r[ix.actScope]).split(/[,،;\r\n]+/).map(function (x) { return x.trim(); }).filter(Boolean) : []
    });
  }
  return staff;
}

/**
 * Everybody the manager supervises (recursively, any depth, cycle-safe).
 * A supervisor only reaches people of a STRICTLY lower tier than the person
 * they report to. T4 sees every other staff member. T1 supervises nobody.
 */
function superviseesOf_(manager, staff) {
  if (manager.tier === "T4") return staff.filter(function (s) { return s.row !== manager.row; });
  if (manager.rank < 2) return [];
  const result = [];
  const seen = {};
  seen[manager.row] = true;
  const queue = [manager];
  while (queue.length) {
    const cur = queue.shift();
    staff.forEach(function (s) {
      if (seen[s.row]) return;
      if (s.rank >= cur.rank) return;
      const reports = s.supervisors.indexOf(cur.normName) !== -1 || (cur.email && s.supervisors.indexOf(cur.email) !== -1);
      if (reports) { seen[s.row] = true; result.push(s); queue.push(s); }
    });
  }
  return result;
}

function looksLikeDate_(rawCell, str) {
  return rawCell instanceof Date || /^\d{4}-\d{1,2}-\d{1,2}/.test(str) || /^\d{1,2}\/\d{1,2}\/\d{4}/.test(str);
}

/**
 * Courses + ownership. Owner = the staff member whose full name equals the
 * course's current teacher (column A). If that is not unique/known, the exact
 * code prefix (unique among staff) is used. No fuzzy matching anywhere.
 */
function loadCourses_(tbl, staff) {
  const v = tbl.values, d = tbl.display, ix = tbl.idx;
  const byName = {}, byPrefix = {};
  staff.forEach(function (s) {
    if (s.normName) (byName[s.normName] = byName[s.normName] || []).push(s);
    if (s.normPrefix) (byPrefix[s.normPrefix] = byPrefix[s.normPrefix] || []).push(s);
  });
  const courses = [];
  for (let i = 1; i < v.length; i++) {
    const r = v[i];
    const dr = d[i] || [];
    if (!r || r.every(function (c) { return cleanVal(c) === ""; })) continue;
    const code = cleanVal(r[ix.code]);
    const teacherStr = cleanVal(dr[ix.teacher] !== undefined && dr[ix.teacher] !== "" ? dr[ix.teacher] : r[ix.teacher]);
    if (!code && !teacherStr) continue;
    const nc = normCode(code);
    const sc = splitCode(nc);
    const flags = [];
    let owner = null, ownerBy = "";

    const corrupted = looksLikeDate_(r[ix.teacher], teacherStr) || (sc && /^\d{4,}$/.test(sc.prefix));
    const pseudo = isUnassignedNorm(nc);
    if (corrupted) flags.push("CORRUPTED");
    if (pseudo) flags.push("PSEUDO");

    if (!corrupted && !pseudo) {
      const nameList = teacherStr ? (byName[normName(teacherStr)] || []) : [];
      const prefList = sc ? (byPrefix[sc.prefix] || []) : [];
      if (nameList.length === 1) { owner = nameList[0]; ownerBy = "name"; }
      else if (prefList.length === 1) { owner = prefList[0]; ownerBy = "prefix"; }
      if (owner && prefList.length === 1 && prefList[0].row !== owner.row) flags.push("PREFIX_MISMATCH");
      if (nameList.length > 1) flags.push("AMBIGUOUS_NAME");
      if (!owner) flags.push("NO_OWNER");
    }

    courses.push({
      row: i + 1,
      code: code,
      normCode: nc,
      codeInfo: sc,
      teacherRaw: teacherStr,
      category: cleanVal(r[ix.category]),
      day: cleanVal(r[ix.day]),
      timing: formatTiming_(dr[ix.time], r[ix.time]),
      place: cleanVal(r[ix.place]),
      venue: cleanVal(r[ix.venue]),
      book: cleanVal(r[ix.book]),
      home: ix.home !== undefined && ix.home !== -1 ? cleanVal(r[ix.home]) : "",
      status: (ix.status !== undefined && ix.status !== -1 && cleanVal(r[ix.status])) || "نشط",
      stopReason: ix.stopReason !== undefined && ix.stopReason !== -1 ? cleanVal(r[ix.stopReason]) : "",
      owner: owner,
      ownerBy: ownerBy,
      flags: flags
    });
  }
  return courses;
}

function loadStudents_(tbl) {
  const v = tbl.values, ix = tbl.idx, out = [];
  for (let i = 1; i < v.length; i++) {
    const r = v[i];
    const name = cleanVal(r[ix.name]);
    if (!name || name === "الاسم" || name.indexOf("معلومات عن الطالب") !== -1) continue;
    const codesStr = cleanVal(r[ix.codes]);
    const codes = parseCodes(codesStr);
    const lastTeacher = cleanVal(r[ix.lastTeacher]);
    out.push({
      row: i + 1,
      id: cleanVal(r[ix.id]),
      name: name,
      normName: normName(name),
      category: cleanVal(r[ix.category]),
      ageGroup: normAge_(r[ix.ageGroup]),
      level: cleanVal(r[ix.level]),
      city: cleanVal(r[ix.city]),
      location: cleanVal(r[ix.location]),
      phone: cleanVal(r[ix.phone]),
      codesStr: codesStr,
      codes: codes,
      lastTeacher: lastTeacher,
      normLastTeacher: normName(lastTeacher),
      completedBooks: cleanVal(r[ix.completedBooks]),
      unassigned: codes.length === 0 || codes.every(function (c) { return isUnassignedNorm(c.norm); })
    });
  }
  return out;
}

/**
 * THE single source of truth for "what can this user see / touch".
 * Used by init AND by every write action.
 */
function buildScope_(user, staff, courses) {
  const supervisees = superviseesOf_(user, staff);
  const rows = {};
  supervisees.forEach(function (s) { rows[s.row] = true; });
  const isAdmin = user.tier === "T4";
  const visible = [], own = [], allowedCodes = {}, ownCodes = {};
  const teacherNames = {};
  teacherNames[user.normName] = true;
  supervisees.forEach(function (s) { teacherNames[s.normName] = true; });

  courses.forEach(function (c) {
    const isOwn = !!(c.owner && c.owner.row === user.row);
    const isSup = !!(c.owner && rows[c.owner.row]);
    if (isOwn || isSup || isAdmin) {
      visible.push(c);
      allowedCodes[c.normCode] = true;
      if (isOwn) { own.push(c); ownCodes[c.normCode] = true; }
    }
  });
  return {
    isAdmin: isAdmin,
    supervisees: supervisees,
    superviseeRows: rows,
    visible: visible,
    own: own,
    allowedCodes: allowedCodes,
    ownCodes: ownCodes,
    teacherNames: teacherNames
  };
}

function studentInScope_(st, scope) {
  if (scope.isAdmin) return true;
  for (let i = 0; i < st.codes.length; i++) if (scope.allowedCodes[st.codes[i].norm]) return true;
  if (st.unassigned && st.normLastTeacher && scope.teacherNames[st.normLastTeacher]) return true;
  return false;
}

function courseInScope_(course, scope) { return !!scope.allowedCodes[course.normCode]; }

/* ============================ DROPDOWN LISTS =========================== */

function extractListOptions_(sheet, colIdx, numeric) {
  if (!sheet || colIdx < 0) return [];
  if (!(RC_.on && !RC_.dirty && sheet._rcName)) return extractListOptionsLive_(sheet, colIdx, numeric);
  const k = "o:" + rcNames_().indexOf(sheet._rcName) + ":" + colIdx + ":" + (numeric ? 1 : 0);
  let out = rcGet_(k);
  if (!Array.isArray(out)) { out = extractListOptionsLive_(sheet, colIdx, numeric); rcPut_(k, out); }
  return out;
}

function extractListOptionsLive_(sheet, colIdx, numeric) {
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const n = Math.min(lastRow - 1, 400);
  const set = {};
  const order = [];
  function add(x) { const t = cleanVal(x); if (t && !set[t]) { set[t] = true; order.push(t); } }
  try {
    const rules = sheet.getRange(2, colIdx + 1, n, 1).getDataValidations();
    for (let r = 0; r < rules.length; r++) {
      const rule = rules[r] && rules[r][0];
      if (rule && rule.getCriteriaType() === SpreadsheetApp.DataValidationCriteria.VALUE_IN_LIST) {
        const args = rule.getCriteriaValues()[0];
        if (Array.isArray(args)) args.forEach(add);
        if (order.length > 0) return sortList_(order, numeric);
      }
    }
  } catch (e) { /* fall back to distinct values */ }
  const vals = sheet.getRange(2, colIdx + 1, n, 1).getValues();
  vals.forEach(function (row) { const t = cleanVal(row[0]); if (t && t !== "-" && t.length < 30) add(t); });
  return sortList_(order, numeric);
}

function sortList_(arr, numeric) {
  const a = arr.slice();
  if (numeric) a.sort(function (x, y) { return (parseFloat(x) || 0) - (parseFloat(y) || 0); });
  else a.sort(function (x, y) { return x.localeCompare(y, "ar"); });
  return a;
}

/* ============================== LOGGING ================================ */

function recordLog(ss, teacherName, teacherEmail, actionType, details) {
  try {
    let sheet = findSheet_(ss, SHEET_NAMES.LOGS);
    if (!sheet) {
      sheet = ss.insertSheet(SHEET_NAMES.LOGS[0]);
      sheet.appendRow(["التاريخ والوقت", "اسم المدرس", "البريد الإلكتروني", "نوع العملية", "التفاصيل"]);
      sheet.setRightToLeft(true);
    }
    const now = fmtDate_(new Date(), "yyyy-MM-dd HH:mm:ss");
    const safe = function (x) { const s = cleanVal(x).slice(0, 500); return /^[=+\-@]/.test(s) ? "'" + s : s; };
    sheet.appendRow([now, safe(teacherName), safe(teacherEmail), safe(actionType), safe(details)]);
  } catch (e) {
    Logger.log("log failed: " + e);
  }
}

/* ============================ AUTH & SESSIONS ========================== */

function getProp_(k) { return PropertiesService.getScriptProperties().getProperty(k); }

function pinSalt_() {
  const salt = getProp_("PIN_SALT");
  if (!salt) fail_("CONFIG", "لم يتم إعداد الأمان بعد. شغّل الدالة setupSecurity من المحرر.");
  return salt;
}
function hex_(bytes) { return bytes.map(function (b) { return ("0" + (b & 0xff).toString(16)).slice(-2); }).join(""); }

/** Legacy hash (v2–v49): "h1:" + hex(sha256(salt|email|pin)). Only verified, never written any more. */
function hashPinV1_(pin, email) {
  const bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, pinSalt_() + "|" + String(email).toLowerCase() + "|" + pin, Utilities.Charset.UTF_8);
  return "h1:" + hex_(bytes);
}
/** v50 hash: "h2:<rounds>:" + hex(sha256^rounds(salt|email|pin)) — slow on purpose. */
function hashPinV2_(pin, email, rounds) {
  const n = rounds || CFG.PIN_HASH_ROUNDS;
  let bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, pinSalt_() + "|" + String(email).toLowerCase() + "|" + pin, Utilities.Charset.UTF_8);
  for (let i = 1; i < n; i++) bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, bytes);
  return "h2:" + n + ":" + hex_(bytes);
}
/** v58: an "h1" hash, or an "h2" hash made with another number of rounds, is re-made at the next successful login. */
function pinNeedsRehash_(stored) {
  const h = cleanVal(stored);
  if (h.indexOf("h1:") === 0) return true;
  const m = /^h2:(\d+):/.exec(h);
  return !!m && Number(m[1]) !== CFG.PIN_HASH_ROUNDS;
}
/** What every new PIN gets. */
function hashPin_(pin, email) { return hashPinV2_(pin, email); }
function verifyPin_(pin, email, stored) {
  stored = cleanVal(stored);
  if (stored.indexOf("h2:") === 0) {
    const n = parseInt(stored.split(":")[1], 10);
    if (!(n > 0 && n <= 20000)) return false;
    return safeEqual_(hashPinV2_(pin, email, n), stored);
  }
  if (stored.indexOf("h1:") === 0) return safeEqual_(hashPinV1_(pin, email), stored);
  return false;
}

function safeEqual_(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}

function genPin_(digits) {
  const d = digits || CFG.PIN_DIGITS;
  let out = "";
  while (out.length < d) {
    const h = Utilities.getUuid().replace(/-/g, "");
    out += String(parseInt(h.slice(0, 12), 16) % 1000000);
  }
  return out.slice(0, d);
}
/** Longer PINs for the accounts that open the most data. */
function pinDigitsFor_(person) {
  const raw = person && person.roleRaw;
  const high = parseTier(raw) === "T4" && hasEduRole_(raw) || ceoOf_(raw) || actTierOf_(raw) === "A4" || canViewAs_(person && person.email);
  return high ? CFG.PIN_DIGITS_HIGH : CFG.PIN_DIGITS;
}

/* ---- per-account session version: bumping it ends every session already open for that e-mail ---- */
function sessVer_(email) { return parseInt(getProp_("sv:" + String(email).toLowerCase()) || "0", 10) || 0; }
function bumpSessVer_(email) {
  const e = String(email).toLowerCase();
  PropertiesService.getScriptProperties().setProperty("sv:" + e, String(sessVer_(e) + 1));
}

/* ---- progressive lockout. Real accounts: script properties (durable). Unknown e-mails: cache only. ---- */
function lockKey_(email) { return "lk:" + String(email).toLowerCase(); }
function lockState_(email, known) {
  let raw = null;
  try { raw = known ? getProp_(lockKey_(email)) : CacheService.getScriptCache().get(lockKey_(email)); } catch (e) { raw = null; }
  let st = null;
  try { st = raw ? JSON.parse(raw) : null; } catch (e) { st = null; }
  if (!st || typeof st !== "object") st = { f: 0, lv: 0, until: 0, t: 0 };
  return st;
}
function saveLock_(email, known, st) {
  const v = JSON.stringify(st);
  if (known) PropertiesService.getScriptProperties().setProperty(lockKey_(email), v);
  else CacheService.getScriptCache().put(lockKey_(email), v, 21600);
}
function isLocked_(email, known) { const st = lockState_(email, known); return !!st.until && Date.now() < st.until; }
function noteFailure_(email, known) {
  const now = Date.now(), st = lockState_(email, known);
  if (st.t && now - st.t > CFG.LOCK_RESET_MS) { st.f = 0; st.lv = 0; }
  st.f = (st.f || 0) + 1; st.t = now;
  if (st.f >= CFG.MAX_FAILED_LOGINS) {
    const steps = CFG.LOCK_STEPS_SEC, sec = steps[Math.min(st.lv || 0, steps.length - 1)];
    st.until = now + sec * 1000; st.lv = (st.lv || 0) + 1; st.f = 0;
  }
  saveLock_(email, known, st);
}
/** Lifts the lockout of one e-mail (editor helper and PIN reset). */
function unlockAccount_(email) {
  const e = String(email).toLowerCase();
  PropertiesService.getScriptProperties().deleteProperty(lockKey_(e));
  const c = CacheService.getScriptCache();
  c.remove(lockKey_(e)); c.remove("fail:" + e);
}
/** E-mails that can log in (have a PIN hash), cached a few minutes. */
function staffEmailSet_(ss, refresh) {
  const cache = CacheService.getScriptCache();
  if (!refresh) {
    const raw = cache.get("staffEmails");
    if (raw) { try { return JSON.parse(raw); } catch (e) { /* rebuild */ } }
  }
  const set = {};
  loadStaff_(readTable_(ss, "teachers"), true).forEach(function (s) { if (s.email && s.pinHash) set[s.email] = 1; });
  try { cache.put("staffEmails", JSON.stringify(set), CFG.STAFF_EMAILS_TTL_SEC); } catch (e) { /* too big: no cache */ }
  return set;
}

function findStaffByEmail_(staff, email) {
  const e = cleanVal(email).toLowerCase();
  if (!e) return null;
  for (let i = 0; i < staff.length; i++) if (staff[i].email === e) return staff[i];
  return null;
}

function publicUser_(user, detectedLocation) {
  return {
    name: user.name,
    email: user.email,
    prefix: user.prefix || user.name.split(" ")[0],
    location: user.location || detectedLocation || "",
    role: user.roleRaw || "T1",
    accessTier: user.tier,
    supervisor: user.supervisorRaw || "",
    isAdmin: user.tier === "T4",
    isSupervisor: user.rank >= 2
  };
}

function actionLogin_(ss, p) {
  if (typeof p.email !== "string" || typeof p.pin !== "string") fail_("BAD_INPUT", "طلب غير صالح.");
  const email = cleanVal(p.email).toLowerCase();
  const pin = cleanVal(p.pin);
  if (!email) fail_("BAD_INPUT", "يرجى كتابة البريد الإلكتروني.");
  if (!pin) fail_("BAD_INPUT", "يرجى إدخال الرمز السري.");
  if (email.length > 120 || pin.length > 32) fail_("BAD_CREDENTIALS", CFG.GENERIC_LOGIN_ERROR);

  const cache = CacheService.getScriptCache();
  const hour = fmtDate_(new Date(), "yyyyMMddHH");
  const gKey = "gfail:" + hour;
  const bumpGlobal = function () { cache.put(gKey, String((parseInt(cache.get(gKey) || "0", 10) || 0) + 1), 3700); };
  const flood = (parseInt(cache.get(gKey) || "0", 10) || 0) >= CFG.GLOBAL_FAIL_PER_HOUR;
  const lockedMsg = "تم تعليق الدخول مؤقتاً بسبب محاولات خاطئة متكررة. أعد المحاولة لاحقاً.";

  let set = staffEmailSet_(ss, false);
  if (!set[email] && !flood) set = staffEmailSet_(ss, true);   // a person added in the last minutes
  if (!set[email]) {
    // unknown e-mail: same answers as a real account, but nothing is read and only a summary is logged
    if (isLocked_(email, false)) fail_("LOCKED", lockedMsg);
    noteFailure_(email, false);
    bumpGlobal();
    const uKey = "ufail:" + hour, u = (parseInt(cache.get(uKey) || "0", 10) || 0) + 1;
    cache.put(uKey, String(u), 3700);
    if (u === 1 || u === 10 || u === 100 || u === 1000 || u === 10000) recordLog(ss, "غير معروف", "", "محاولات دخول ببريد غير معروف", u + " محاولة خلال هذه الساعة");
    fail_("BAD_CREDENTIALS", CFG.GENERIC_LOGIN_ERROR);
  }
  if (isLocked_(email, true)) fail_("LOCKED", lockedMsg);

  const tbl = readTable_(ss, "teachers");
  const staff = loadStaff_(tbl);
  const everyone = loadStaff_(tbl, true);
  const user = findStaffByEmail_(staff, email);
  const act = actFindByEmail_(actLoadTeam_(ss, everyone), email);
  const ceo = ceoFindByEmail_(everyone, email);
  // either department's PIN opens the account; the profiles available are every department the e-mail belongs to
  let hit = null;
  const tried = {};
  [user, act, ceo].some(function (x) {
    if (!x || !x.pinHash || tried[x.pinHash]) return false;   // the same row is often both profiles: hash once (v51)
    tried[x.pinHash] = true;
    if (verifyPin_(pin, email, x.pinHash)) { hit = x; return true; }
    return false;
  });

  if (!hit) {
    noteFailure_(email, true);
    bumpGlobal();
    recordLog(ss, user ? user.name : (act ? act.name : (ceo ? ceo.name : "غير معروف")), email, "محاولة دخول فاشلة", "");
    fail_("BAD_CREDENTIALS", CFG.GENERIC_LOGIN_ERROR);
  }

  unlockAccount_(email);
  if (pinNeedsRehash_(hit.pinHash) && hit.row && tbl.idx.pinHash !== -1) {
    try { tbl.sheet.getRange(hit.row, tbl.idx.pinHash + 1).setValue(hashPinV2_(pin, email)); } catch (e) { Logger.log("hash upgrade failed: " + e); }
  }
  const token = (Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, "");
  cache.put("sess:" + token, JSON.stringify({ email: email, sv: sessVer_(email) }), CFG.SESSION_TTL_SEC);
  const departments = [];
  if (user) departments.push("edu");
  if (act) departments.push("act");
  if (ceo) departments.push("ceo");
  recordLog(ss, user ? user.name : (act ? act.name : ceo.name), email, "دخول", (user ? "الصلاحية: " + user.tier : "") + (act ? " | الأنشطة: " + act.tier : "") + (ceo ? " | T5" : ""));

  const canView = canViewAs_(email) || !!ceo;
  const tiers = { edu: user ? user.tier : "", act: act ? (act.tier || (act.majlis ? "M1" : "")) : "" };   // v57: tab labels before the data arrives
  if (p.lite === true || !user) return { success: true, token: token, departments: departments, canViewAs: canView, tiers: tiers };   // fast path: data is fetched by separate "init" / "actInit" calls
  const ctx = { ss: ss, staff: staff, user: user, token: token };
  const data = buildInit_(ctx);
  data.token = token;
  data.departments = departments;
  data.canViewAs = canView;
  return data;
}

function requireCtx_(ss, token) {
  const t = cleanVal(token);
  const expired = function () { fail_("SESSION_EXPIRED", "انتهت الجلسة، يرجى تسجيل الدخول من جديد."); };
  if (!/^[a-f0-9]{64}$/.test(t)) expired();
  const raw = CacheService.getScriptCache().get("sess:" + t);
  if (!raw) expired();
  let email = "", viewer = "", readOnly = false, sv = null;
  try { const o = JSON.parse(raw); email = o.email; viewer = o.viewer || ""; readOnly = o.ro === true; sv = (o.sv === undefined ? null : Number(o.sv)); } catch (e) { expired(); }
  const cur = sessVer_(email);
  if ((sv === null && cur > 0) || (sv !== null && sv !== cur)) expired();   // PIN reset / «قطع الجلسات» since this token was issued
  const tbl = readTable_(ss, "teachers");
  const staff = loadStaff_(tbl);
  const everyone = loadStaff_(tbl, true);
  const user = findStaffByEmail_(staff, email);
  const act = actFindByEmail_(actLoadTeam_(ss, everyone), email);
  const ceo = ceoFindByEmail_(everyone, email);
  if (!user && !act && !ceo) expired();
  // user = التعليم profile (or null), act = الأنشطة profile (or null). Each action family checks its own.
  return { ss: ss, staff: staff, user: user, act: act, ceo: ceo, token: t, email: email, viewer: viewer, readOnly: readOnly };
}

function withLock_(fn) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(CFG.LOCK_WAIT_MS)) fail_("BUSY", "الخادم مشغول حالياً، أعد المحاولة بعد لحظات.");
  try { return fn(); } finally { lock.releaseLock(); }
}

/* ============================ v51: READ CACHE ========================== */
/*
 * Read-only actions (READ_ACTIONS) see the spreadsheet through a snapshot kept in the
 * script's own CacheService (inside Google, readable only by this script — never by a
 * browser or a phone). What is cached is the RAW sheet content, never a per-person
 * answer: every request still checks the session and filters by role exactly as before.
 *
 *  - PIN hashes never enter the cache (the PIN_HASH column is replaced by "•").
 *  - Every snapshot key carries a data version ("rc:dv"). Any write action, any change
 *    made by hand in the spreadsheet (installCacheTrigger) and invalidateReadCache()
 *    replace that version, so the next read is fresh. CFG.READ_CACHE_SEC is the
 *    safety net if a change was missed.
 *  - Write actions never use the cache: they read the live sheet under the lock.
 *  - If a read action has to write (e.g. it repairs a header), the snapshot is dropped
 *    for the rest of that request and the version is replaced afterwards.
 *  - Any cache problem (missing part, too large, corrupt) silently falls back to the
 *    live sheet.
 */
const READ_ACTIONS = { init: true, actInit: true, ceoInit: true, actContribInit: true, majlisInit: true, actClassInit: true, majlisSearch: true, viewAsList: true, pubLoad: true, pubSearch: true, areaList: true };
const RC_CHUNK = { z: 90000, j: 30000 };     // characters per cache value (limit: 100 KB per value)
const RC_MAX_PARTS = 40;
const RC_ = { on: false, dirty: false, dv: null, real: null, names: null, snaps: {}, disp: {}, sheets: {}, cache: null, action: "", pre: null, manifest: {}, used: {}, vers: {}, live: null };

function rcReset_(on, action) {
  RC_.on = !!on && CFG.READ_CACHE_SEC > 0;
  RC_.dirty = false; RC_.dv = null; RC_.real = null; RC_.names = null;
  RC_.snaps = {}; RC_.disp = {}; RC_.sheets = {}; RC_.cache = null;
  RC_.action = action || ""; RC_.pre = null; RC_.manifest = {}; RC_.used = {}; RC_.force = false; RC_.vers = {}; RC_.live = null;
}

/* ---- v58: which sheets each write action may change (verified by the test suites on every write) ---- */
function W_() {
  const out = [];
  for (let i = 0; i < arguments.length; i++) { const a = arguments[i]; (Array.isArray(a) ? a : [a]).forEach(function (n) { if (out.indexOf(n) === -1) out.push(n); }); }
  return out;
}
let WRITES_ = null;
function writesMap_() {
  if (WRITES_) return WRITES_;
  const T = SHEET_NAMES, P = SHEETS_P1;
  const LOG = T.LOGS, ST = T.STUDENTS, CO = T.COURSES, AT = T.ATTENDANCE;
  const RQ = [RQ_SHEET.name, RQ_EVENTS.name];
  WRITES_ = WRITES_SPEC_(T, P, LOG, ST, CO, AT, RQ);
  return WRITES_;
}
/** A write to the first sheet also changes what the formulas of the second ones show. */
function rcDependents_(name) {
  const n = normalizeArabic(name).replace(/\s+/g, "");
  const is = function (list) { return list.some(function (x) { return normalizeArabic(x).replace(/\s+/g, "") === n; }); };
  if (is(SHEET_NAMES.STUDENTS) || is(SHEET_NAMES.SYLLABUS)) return SHEET_NAMES.COURSES.slice();   // عدد الطلاب, التقدم في الكتاب
  return [];
}

/** The decoded value stored under a full cache key, or null (used outside a read request). */
function rcGetFull_(key) {
  try {
    const c = CacheService.getScriptCache(), first = c.getAll([key, key + ":0"]);
    const n = parseInt(first[key], 10);
    if (!(n >= 1 && n <= RC_MAX_PARTS) || typeof first[key + ":0"] !== "string") return null;
    const parts = [first[key + ":0"]];
    if (n > 1) {
      const ks = []; for (let i = 1; i < n; i++) ks.push(key + ":" + i);
      const rest = c.getAll(ks);
      for (let j = 0; j < ks.length; j++) { if (typeof rest[ks[j]] !== "string") return null; parts.push(rest[ks[j]]); }
    }
    return rcDecode_(parts.join(""));
  } catch (e) { return null; }
}

/**
 * New version for the given sheets (and their dependents). Call it holding the script lock.
 * Anything unexpected (no names list yet, a sheet created by this write, cache error) → full invalidation.
 */
function bumpSheets_(names) {
  const c = CacheService.getScriptCache();
  const got = c.getAll(["rc:dv", "rc:vers"]);
  const dv = got["rc:dv"];
  if (!dv) return;                                     // nothing is cached
  const list = rcGetFull_("rc:" + dv + ":n");
  if (!Array.isArray(list)) { bumpDataVer_(); return; }
  const norm = function (x) { return normalizeArabic(x).replace(/\s+/g, ""); };
  const idxOf = {}; list.forEach(function (n, i) { idxOf[norm(n)] = i; });
  let vers = null;
  try { vers = got["rc:vers"] ? JSON.parse(got["rc:vers"]) : null; } catch (e) { vers = null; }
  if (!vers || vers.dv !== dv || !vers.v) vers = { dv: dv, v: {} };
  const all = [];
  names.forEach(function (n) { all.push(n); rcDependents_(n).forEach(function (d) { all.push(d); }); });
  for (let i = 0; i < all.length; i++) {
    const k = idxOf[norm(all[i])];
    if (k === undefined) {
      // not in the cached list: either it does not exist (nothing to do) or this write just created it (→ full)
      if (RC_.live && RC_.live.getSheetByName(all[i])) { bumpDataVer_(); return; }
      continue;
    }
    vers.v[k] = Utilities.getUuid().replace(/-/g, "").slice(0, 8);
  }
  c.put("rc:vers", JSON.stringify(vers), 21600);
}
function bumpSheetsLocked_(names) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(5000)) { bumpDataVer_(); return; }
  try { bumpSheets_(names); } catch (e) { Logger.log("bumpSheets: " + e); bumpDataVer_(); } finally { lock.releaseLock(); }
}

/** After a read action: remember which cache entries it used, so the next one fetches them all in one call. */
function rcSaveManifest_() {
  try {
    if (!RC_.on || RC_.dirty || !RC_.action) return;
    const extra = Object.keys(RC_.used).filter(function (k) { return !RC_.manifest[k]; });
    if (!extra.length) return;
    rcCache_().put("rc:m:" + RC_.action, JSON.stringify(Object.keys(RC_.manifest).concat(extra)), 21600);
  } catch (e) { /* only an optimisation */ }
}
function rcCache_() { return RC_.cache || (RC_.cache = CacheService.getScriptCache()); }
function rcReal_() { return RC_.real || (RC_.real = openSS_()); }
function rcDirty_() { RC_.dirty = true; }

/** Replaces the data version: every cached snapshot becomes unreachable at once. */
function bumpDataVer_() {
  try { CacheService.getScriptCache().put("rc:dv", Utilities.getUuid().replace(/-/g, "").slice(0, 10), 21600); } catch (e) { Logger.log("cache bump failed: " + e); }
}
/**
 * Public (editor / trigger): forget cached snapshots. Installed on the spreadsheet by installCacheTrigger().
 * v58: a hand edit (onEdit, or onChange of type EDIT) only renews the edited sheet; anything structural
 * (rows, columns, sheets added or removed, formatting) or a manual run renews everything.
 */
function invalidateReadCache(e) {
  try {
    let name = "";
    if (e && e.range && typeof e.range.getSheet === "function") name = e.range.getSheet().getName();
    else if (e && e.changeType === "EDIT" && e.source && typeof e.source.getActiveSheet === "function") name = e.source.getActiveSheet().getName();
    if (name) { bumpSheetsLocked_([name]); return; }
  } catch (err) { /* full invalidation below */ }
  bumpDataVer_();
}

function rcDv_() {
  if (RC_.dv) return RC_.dv;
  let dv = null, man = [], vers = null;
  try {
    const got = rcCache_().getAll(["rc:dv", "rc:vers", "rc:m:" + RC_.action]);
    dv = got["rc:dv"] || null;
    if (got["rc:m:" + RC_.action]) man = JSON.parse(got["rc:m:" + RC_.action]);
    if (got["rc:vers"]) vers = JSON.parse(got["rc:vers"]);
  } catch (e) { dv = null; }
  if (!dv) {
    dv = Utilities.getUuid().replace(/-/g, "").slice(0, 10);
    try { rcCache_().put("rc:dv", dv, 21600); } catch (e) { /* no cache: every read is live */ }
    man = [];   // a new version holds nothing yet
  }
  RC_.dv = dv;
  RC_.vers = (vers && vers.dv === dv && vers.v && typeof vers.v === "object") ? vers.v : {};
  if (Array.isArray(man) && man.length) {
    const keys = [];
    man.forEach(function (k) { if (typeof k === "string") { RC_.manifest[k] = true; keys.push(rcKey_(k), rcKey_(k) + ":0"); } });
    try { RC_.pre = rcCache_().getAll(keys); } catch (e) { RC_.pre = null; }
  }
  return dv;
}
/**
 * v58: a sheet's entries (snapshot "s:", display "d:", dropdowns "o:") also carry that sheet's own version, so a
 * write to one sheet only makes THAT sheet (and the sheets whose formulas read it) be read again.
 */
function rcKey_(k) {
  const dv = rcDv_();
  const m = /^[sdo]:(\d+)/.exec(k);
  return "rc:" + dv + ":" + k + (m ? "@" + (RC_.vers[m[1]] || "0") : "");
}

function rcEncode_(obj) {
  const json = JSON.stringify(obj, function (k, v) { const raw = this[k]; return raw instanceof Date ? { "$d": raw.getTime() } : v; });
  try {
    if (typeof Utilities.gzip === "function") {
      const blob = Utilities.newBlob("", "application/json").setDataFromString(json, "UTF-8");
      return "z" + Utilities.base64Encode(Utilities.gzip(blob).getBytes());
    }
  } catch (e) { /* plain JSON below */ }
  return "j" + json;
}
function rcDecode_(s) {
  const json = s.charAt(0) === "z"
    ? Utilities.ungzip(Utilities.newBlob(Utilities.base64Decode(s.slice(1)), "application/x-gzip")).getDataAsString("UTF-8")
    : s.slice(1);
  return JSON.parse(json, function (k, v) {
    return (v && typeof v === "object" && !Array.isArray(v) && typeof v.$d === "number" && Object.keys(v).length === 1) ? new Date(v.$d) : v;
  });
}

/** Returns the decoded value stored under key k (current version), or null. */
function rcGet_(k) {
  try {
    const key = rcKey_(k), c = rcCache_();
    RC_.used[k] = true;
    if (RC_.force) return null;          // warm-up: rebuild every entry with a fresh lifetime
    const first = (RC_.pre && RC_.manifest[k]) ? RC_.pre : c.getAll([key, key + ":0"]);
    const n = parseInt(first[key], 10);
    if (!(n >= 1 && n <= RC_MAX_PARTS) || typeof first[key + ":0"] !== "string") return null;
    const parts = [first[key + ":0"]];
    if (n > 1) {
      const ks = [];
      for (let i = 1; i < n; i++) ks.push(key + ":" + i);
      const rest = c.getAll(ks);
      for (let j = 0; j < ks.length; j++) { if (typeof rest[ks[j]] !== "string") return null; parts.push(rest[ks[j]]); }
    }
    return rcDecode_(parts.join(""));
  } catch (e) { return null; }
}
function rcPut_(k, obj) {
  try {
    const key = rcKey_(k), s = rcEncode_(obj), size = RC_CHUNK[s.charAt(0)];
    const n = Math.max(1, Math.ceil(s.length / size));
    if (n > RC_MAX_PARTS) return;
    const o = {};
    o[key] = String(n);
    for (let i = 0; i < n; i++) o[key + ":" + i] = s.slice(i * size, (i + 1) * size);
    rcCache_().putAll(o, CFG.READ_CACHE_SEC);
  } catch (e) { Logger.log("cache put skipped: " + e); }
}

function rcNames_() {
  if (RC_.names) return RC_.names;
  let names = rcGet_("n");
  if (!Array.isArray(names)) {
    names = rcReal_().getSheets().map(function (s) { return s.getName(); });
    rcPut_("n", names);
  }
  return (RC_.names = names);
}
function rcCacheable_(name) { return name !== PINS_TEMP_SHEET_NAME; }

/** PIN hashes are replaced before a snapshot is stored (whatever sheet holds a PIN_HASH header). */
function rcScrub_(grid) {
  if (!grid.length) return grid;
  const col = findCol_((grid[0] || []).map(normHeader), SCHEMAS.teachers.cols.pinHash);
  if (col !== -1) for (let r = 1; r < grid.length; r++) if (grid[r] && cleanVal(grid[r][col]) !== "") grid[r][col] = "•";
  return grid;
}

function rcSnap_(name) {
  if (RC_.snaps[name]) return RC_.snaps[name];
  const k = "s:" + rcNames_().indexOf(name);
  let snap = rcGet_(k);
  if (!snap || !Array.isArray(snap.v)) {
    const v = rcReal_().getSheetByName(name).getDataRange().getValues();
    const empty = v.length === 1 && v[0].length === 1 && v[0][0] === "";   // an empty sheet answers one blank cell
    snap = { v: empty ? [] : v, lr: empty ? 0 : v.length, lc: empty ? 0 : v[0].length };
    rcScrub_(snap.v);
    rcPut_(k, snap);
  }
  return (RC_.snaps[name] = snap);
}
function rcDisplay_(name) {
  if (RC_.disp[name]) return RC_.disp[name];
  const k = "d:" + rcNames_().indexOf(name);
  let grid = rcGet_(k);
  if (!Array.isArray(grid)) {
    const snap = rcSnap_(name), sh = rcReal_().getSheetByName(name);
    grid = (snap.lr > 0 && snap.lc > 0) ? sh.getRange(1, 1, snap.lr, snap.lc).getDisplayValues() : [];   // same cells as the values snapshot
    rcScrub_(grid);
    rcPut_(k, grid);
  }
  return (RC_.disp[name] = grid);
}

function rcSlice_(g, r, c, nr, nc) {
  const out = new Array(nr);
  for (let i = 0; i < nr; i++) {
    const src = g[r - 1 + i] || [];
    const row = new Array(nc);
    for (let j = 0; j < nc; j++) {
      const v = src[c - 1 + j];
      row[j] = (v === undefined || v === null) ? "" : (v instanceof Date ? new Date(v.getTime()) : v);
    }
    out[i] = row;
  }
  return out;
}

/** Read-only view of one sheet: reads come from the snapshot, anything else goes to the live sheet. */
function rcSheet_(name) {
  if (RC_.sheets[name]) return RC_.sheets[name];
  let live = null;
  const real = function () { return live || (live = rcReal_().getSheetByName(name)); };
  const snap = function () { return rcSnap_(name); };
  const write = function (fn) { return function () { rcDirty_(); const s = real(); return s[fn].apply(s, arguments); }; };
  const sh = {
    _rcName: name,
    _real: real,
    getName: function () { return name; },
    getLastRow: function () { return RC_.dirty ? real().getLastRow() : snap().lr; },
    getLastColumn: function () { return RC_.dirty ? real().getLastColumn() : snap().lc; },
    getMaxRows: function () { return real().getMaxRows(); },          // rarely needed: asked live
    getMaxColumns: function () { return real().getMaxColumns(); },
    getDataRange: function () {
      if (RC_.dirty) return real().getDataRange();
      const s = snap();
      return rcRange_(sh, 1, 1, Math.max(s.lr, 1), Math.max(s.lc, 1));
    },
    getRange: function (r, c, nr, nc) {
      if (RC_.dirty || typeof r !== "number") { if (typeof r !== "number") rcDirty_(); const s = real(); return s.getRange.apply(s, arguments); }
      return rcRange_(sh, r, c, nr || 1, nc || 1);
    }
  };
  ["appendRow", "deleteRow", "deleteRows", "insertRowsAfter", "insertRowsBefore", "insertColumnsAfter", "insertColumnsBefore",
   "setRightToLeft", "setName", "clear", "clearContents", "setFrozenRows", "hideSheet", "showSheet", "sort", "activate"].forEach(function (fn) { sh[fn] = write(fn); });
  return (RC_.sheets[name] = sh);
}

function rcRange_(sh, r, c, nr, nc) {
  let live = null;
  const real = function () { return live || (live = sh._real().getRange(r, c, nr, nc)); };
  const write = function (fn) {
    return function () {
      rcDirty_();
      const args = Array.prototype.slice.call(arguments).map(function (a) { return (a && typeof a._real === "function") ? a._real() : a; });
      const x = real(); return x[fn].apply(x, args);
    };
  };
  const rg = {
    _real: real,
    getRow: function () { return r; }, getColumn: function () { return c; },
    getNumRows: function () { return nr; }, getNumColumns: function () { return nc; },
    getValues: function () { return RC_.dirty ? real().getValues() : rcSlice_(rcSnap_(sh._rcName).v, r, c, nr, nc); },
    getValue: function () { return rg.getValues()[0][0]; },
    getDisplayValues: function () { return RC_.dirty ? real().getDisplayValues() : rcSlice_(rcDisplay_(sh._rcName), r, c, nr, nc); },
    getDisplayValue: function () { return rg.getDisplayValues()[0][0]; },
    getDataValidations: function () { return real().getDataValidations(); },
    getFormulas: function () { return real().getFormulas(); },
    getFormula: function () { return real().getFormula(); }
  };
  ["setValues", "setValue", "setNumberFormat", "setNumberFormats", "setFontWeight", "setFormula", "setFormulas", "copyTo",
   "clear", "clearContent", "setDataValidation", "setDataValidations", "setBackground", "insertCheckboxes"].forEach(function (fn) { rg[fn] = write(fn); });
  return rg;
}

/** The spreadsheet as seen by a read-only action. */
function rcSS_() {
  return {
    getSheetByName: function (n) {
      if (RC_.dirty || !rcCacheable_(n)) return rcReal_().getSheetByName(n);
      return rcNames_().indexOf(n) === -1 ? null : rcSheet_(n);
    },
    getSheets: function () { return RC_.dirty ? rcReal_().getSheets() : rcNames_().filter(rcCacheable_).map(rcSheet_); },
    insertSheet: function () { rcDirty_(); const s = rcReal_(); return s.insertSheet.apply(s, arguments); },
    deleteSheet: function (x) { rcDirty_(); return rcReal_().deleteSheet(x && typeof x._real === "function" ? x._real() : x); },
    getId: function () { return SPREADSHEET_ID; }
  };
}

/** Editor helpers that change sheet data drop the read cache afterwards. */
function withCacheBump_(fn) {
  try { return fn(); } finally { try { SpreadsheetApp.flush(); } catch (e) { /* nothing pending */ } bumpDataVer_(); }
}

/**
 * Editor, once: (1) a hand edit in the spreadsheet invalidates the cache at once;
 * (2) v57: every WARM_EVERY_MIN minutes the snapshot is rebuilt in the background, so the first
 * person who opens the app does not pay for reading the whole spreadsheet. Safe to run again.
 */
function installCacheTrigger() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    const h = t.getHandlerFunction();
    if (h === "invalidateReadCache" || h === "warmReadCache") ScriptApp.deleteTrigger(t);
  });
  ScriptApp.newTrigger("invalidateReadCache").forSpreadsheet(SPREADSHEET_ID).onEdit().create();
  ScriptApp.newTrigger("invalidateReadCache").forSpreadsheet(SPREADSHEET_ID).onChange().create();
  ScriptApp.newTrigger("warmReadCache").timeBased().everyMinutes(CFG.WARM_EVERY_MIN).create();
  bumpDataVer_();
  warmReadCache({ force: true, anyHour: true });
  const msg = "تم: كل تعديل يدوي يُلغي النسخة المؤقتة فوراً، وتُجدَّد النسخة تلقائياً كل " + CFG.WARM_EVERY_MIN + " دقائق.";
  Logger.log(msg);
  return msg;
}

/** The context a privileged reader would have (server-side only, never a token): one per department. */
function warmCtxs_(ss) {
  const tbl = readTable_(ss, "teachers"), staff = loadStaff_(tbl), everyone = loadStaff_(tbl, true);
  const team = actLoadTeam_(ss, everyone);
  const mk = function (o) { return { ss: ss, staff: staff, user: o.user || null, act: o.act || null, ceo: o.ceo || null, token: "", email: o.email, viewer: "", readOnly: true }; };
  const out = {};
  const t4 = staff.filter(function (s) { return s.tier === "T4" && s.email; })[0];
  if (t4) out.init = mk({ user: t4, email: t4.email });
  const a4 = team.filter(function (a) { return a.tier === "A4"; })[0];
  if (a4) out.actInit = mk({ act: a4, email: a4.email });
  const c5 = everyone.filter(function (s) { return s.ceo && s.email; })[0];
  if (c5) out.ceoInit = mk({ ceo: c5, email: c5.email });
  return out;
}

/** Runs one read action the way a request would, through the cache. Returns its duration in ms (-1: nobody to run it as). */
function warmRun_(action, force) {
  rcReset_(true, action);
  RC_.force = !!force;
  const t0 = Date.now();
  try {
    const ss = rcSS_(), ctx = warmCtxs_(ss)[action];
    if (!ctx) return -1;
    if (action === "init") buildInit_(ctx);
    else if (action === "actInit") actInit_(ctx);
    else if (action === "ceoInit") ceoInit_(ctx, { days: 30 });
    RC_.force = false;
    rcSaveManifest_();
    return Date.now() - t0;
  } finally {
    if (RC_.dirty) { try { SpreadsheetApp.flush(); } catch (e) { /* nothing pending */ } bumpDataVer_(); }
    rcReset_(false);
  }
}

/** Trigger (every WARM_EVERY_MIN minutes, daytime): rebuilds the snapshot so the next login is fast. */
function warmReadCache(opts) {
  if (!(CFG.READ_CACHE_SEC > 0)) return;
  const o = (opts && typeof opts === "object" && !opts.triggerUid) ? opts : {};   // a trigger passes its own event object
  const h = Number(Utilities.formatDate(new Date(), tz_(), "H"));
  if (!o.anyHour && (h < CFG.WARM_HOURS[0] || h >= CFG.WARM_HOURS[1])) return;
  ["init", "actInit", "ceoInit"].forEach(function (a) {
    try { warmRun_(a, o.force !== false); } catch (e) { Logger.log("warm " + a + ": " + e); }
  });
}

/**
 * Editor: measures where the time goes (paste the execution log to the developer).
 * It invalidates the cache once, then times every step cold and warm.
 */
function measureSpeed() {
  const lines = [];
  const time = function (label, fn) { const t0 = Date.now(); let r = null; try { r = fn(); } catch (e) { lines.push(label + ": خطأ " + e); return null; } lines.push(label + ": " + (Date.now() - t0) + " ms"); return r; };
  const ss = time("فتح الجدول", openSS_);
  time("قراءة فريق التعليم (حيّة)", function () { return readTable_(ss, "teachers"); });
  time("بصمة رمز سري (" + CFG.PIN_HASH_ROUNDS + " دورة)", function () { return hashPinV2_("12345678", "speed@test", CFG.PIN_HASH_ROUNDS); });
  time("كتابة سطر في السجل", function () { return recordLog(ss, "قياس السرعة", "", "قياس", "measureSpeed"); });
  bumpDataVer_();
  ["init", "actInit", "ceoInit"].forEach(function (a) {
    lines.push(a + " بدون نسخة مؤقتة: " + warmRun_(a, true) + " ms");
    lines.push(a + " مع النسخة المؤقتة: " + warmRun_(a, false) + " ms");
  });
  Logger.log("===== قياس السرعة =====\n" + lines.join("\n"));
  return lines;
}

/* ============================ READ: INIT DATA ========================== */

function buildInit_(ctx) {
  const ss = ctx.ss, user = ctx.user;
  const courseTbl = readTable_(ss, "courses", true);
  const courses = loadCourses_(courseTbl, ctx.staff);
  const studentTbl = readTable_(ss, "students");
  const students = loadStudents_(studentTbl);
  const scope = buildScope_(user, ctx.staff, courses);

  const outCourses = scope.visible.map(function (c) {
    const isOwn = !!(c.owner && c.owner.row === user.row);
    const pseudo = c.flags.indexOf("PSEUDO") !== -1;
    return {
      code: c.code,
      teacher: c.owner ? c.owner.name : (c.teacherRaw || (pseudo ? "بلا درس" : "مدرس غير محدد")),
      teacherTier: c.owner ? c.owner.tier : "T1",
      supervisor: c.owner ? c.owner.supervisorRaw : "",
      book: c.book || c.code,
      day: c.day,
      timing: c.timing,
      location: c.place || "مقر",
      home: c.home || "",
      status: c.status || "نشط",
      stopReason: c.status === "متوقف" ? (c.stopReason || "") : "",
      venue: c.venue || "منفلوري",
      category: c.category,
      isOwnCourse: isOwn
    };
  });

  const outStudents = [];
  students.forEach(function (st) {
    if (!studentInScope_(st, scope)) return;
    outStudents.push({
      id: st.id,
      name: st.name,
      category: st.category,
      ageGroup: st.ageGroup,
      level: st.level || "1",
      city: st.city,
      location: st.location,
      phone: st.phone,
      courseCodes: st.codesStr,
      lastTeacher: st.lastTeacher,
      completedBooks: st.completedBooks,
      isUnassigned: st.unassigned
    });
  });

  // ---- syllabus + books
  const syl = readTable_(ss, "syllabus");
  const syllabus = [];
  const booksSet = {};
  for (let i = 1; i < syl.values.length; i++) {
    const book = cleanVal(syl.values[i][syl.idx.book]);
    const chapter = cleanVal(syl.values[i][syl.idx.chapter]);
    if (book) booksSet[book] = true;
    if (book || chapter) syllabus.push({ book: book, chapter: chapter });
  }
  courses.forEach(function (c) { if (c.book && c.book !== "-" && c.book.length < 50) booksSet[c.book] = true; });
  const excluded = ["المختصر س1", "القول الجلي"];
  const priority = ["أوجز س1", "أوجز س2", "إظهار س1"];
  excluded.forEach(function (b) { delete booksSet[b]; });
  const rest = Object.keys(booksSet).filter(function (b) { return priority.indexOf(b) === -1; }).sort(function (a, b) { return a.localeCompare(b, "ar"); });
  const books = priority.concat(rest);

  // ---- attendance (only allowed courses, last N months)
  const attTbl = readTable_(ss, "attendance");
  const cutoffD = new Date();
  cutoffD.setMonth(cutoffD.getMonth() - CFG.ATTENDANCE_MONTHS);
  const cutoff = fmtDate_(cutoffD, "yyyy-MM-dd");
  const attendance = [];
  const ai = attTbl.idx;
  for (let r = 1; r < attTbl.values.length; r++) {
    const row = attTbl.values[r];
    const code = cleanVal(row[ai.code]);
    if (!code) continue;
    if (!scope.isAdmin && !scope.allowedCodes[normCode(code)]) continue;
    const date = toISODate_(row[ai.date]);
    if (!date || date < cutoff) continue;
    const rawVal = row[ai.value];
    const num = Number(rawVal);
    const status = cleanVal(row[ai.status]);
    const value = (cleanVal(rawVal) !== "" && !isNaN(num)) ? (num === 1 ? 1 : 0) : (status === "حاضر" ? 1 : 0);
    attendance.push({
      courseCode: code,
      date: date,
      lastTopic: cleanVal(row[ai.lastTopic]),
      studentName: cleanVal(row[ai.student]),
      status: status || (value === 1 ? "حاضر" : "غائب"),
      value: value
    });
  }

  // ---- dropdowns
  const venueList = extractListOptions_(courseTbl.sheet, courseTbl.idx.venue, false)
    .concat(extractListOptions_(studentTbl.sheet, studentTbl.idx.location, false))
    .concat(["منفلوري", "المرسى", "أريانة"]);
  const venues = [];
  venueList.forEach(function (v) {
    if (v && CFG.PLACES.indexOf(v) === -1 && venues.indexOf(v) === -1) venues.push(v);
  });
  const cats = extractListOptions_(courseTbl.sheet, courseTbl.idx.category, false);
  const levels = extractListOptions_(studentTbl.sheet, studentTbl.idx.level, true);
  const agesRaw = extractListOptions_(studentTbl.sheet, studentTbl.idx.ageGroup, false);
  const ages = CFG.AGE_GROUPS.slice();
  agesRaw.forEach(function (a) { const n = normAge_(a); if (n && ages.indexOf(n) === -1) ages.push(n); });

  let detectedLocation = "";
  for (let k = 0; k < scope.own.length; k++) { if (scope.own[k].venue) { detectedLocation = scope.own[k].venue; break; } }

  const result = {
    success: true,
    user: publicUser_(user, detectedLocation),
    courses: outCourses,
    students: outStudents,
    syllabus: syllabus,
    books: books,
    attendance: attendance,
    dropdowns: {
      courseCategories: cats.length ? cats : ["رجال", "نساء"],
      locations: CFG.PLACES.slice(),
      venues: venues,
      studentLevels: levels.length ? levels : ["1", "2", "3", "4", "5", "6"],
      studentCategories: CFG.STUDENT_CATEGORIES.slice(),
      studentAgeGroups: ages
    }
  };
  const p1 = buildPhase1Data_(ctx, courses, courseTbl, scope);
  Object.keys(p1).forEach(function (k) { result[k] = p1[k]; });
  const p2 = buildPhase2Data_(ctx, scope);
  Object.keys(p2).forEach(function (k) { result[k] = p2[k]; });
  if (user.tier === "T4") {
    const issues = computeHealth_(ctx.staff, courses, students);
    result.warnings = summarizeHealth_(issues);
  }
  return result;
}

/* ============================ WRITE ACTIONS ============================ */

function loadWorld_(ctx, withStudents) {
  const courseTbl = readTable_(ctx.ss, "courses", true);
  const courses = loadCourses_(courseTbl, ctx.staff);
  const scope = buildScope_(ctx.user, ctx.staff, courses);
  const w = { courseTbl: courseTbl, courses: courses, scope: scope };
  if (withStudents) {
    w.studentTbl = readTable_(ctx.ss, "students");
    w.students = loadStudents_(w.studentTbl);
  }
  return w;
}

function findCourse_(w, code) {
  const n = normCode(text_(code, 60, "رمز الدرس", true));
  for (let i = 0; i < w.courses.length; i++) if (w.courses[i].normCode === n) return w.courses[i];
  return null;
}

function enum_(v, list, label) {
  const s = cleanVal(v);
  if (list.indexOf(s) === -1) fail_("BAD_INPUT", label + " غير صالح.");
  return s;
}

function timeVal_(v) {
  const s = cleanVal(v);
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(s)) fail_("BAD_INPUT", "التوقيت غير صالح.");
  return s;
}

function has_(p, k) { return Object.prototype.hasOwnProperty.call(p, k) && p[k] !== undefined && p[k] !== null; }

function nextStudentId_(students, archived) {
  let max = 0;
  const used = {};
  Object.keys(archived || {}).forEach(function (k) {
    used[k] = true;
    const m0 = /^ST-(\d+)$/.exec(k);
    if (m0) max = Math.max(max, parseInt(m0[1], 10));
  });
  students.forEach(function (s) {
    used[s.id] = true;
    const m = /^ST-(\d+)$/.exec(s.id);
    if (m) max = Math.max(max, parseInt(m[1], 10));
  });
  let n = max + 1, id;
  do { id = "ST-" + ("0000" + n).slice(-4); n++; } while (used[id]);
  return id;
}

function actionSaveAttendance_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const course = findCourse_(w, p.courseCode);
    if (!course) fail_("NOT_FOUND", "الدرس غير موجود.");
    const isOwn = !!(course.owner && course.owner.row === user.row);
    if (!(isOwn || user.tier === "T4")) fail_("FORBIDDEN", "يمكنك تسجيل الحضور لدروسك فقط.");

    const date = cleanVal(p.date);
    if (!validISODate_(date)) fail_("BAD_INPUT", "تاريخ الحصة غير صالح.");
    const lo = fmtDate_(new Date(Date.now() - 370 * 86400000), "yyyy-MM-dd");
    const hi = fmtDate_(new Date(Date.now() + 86400000), "yyyy-MM-dd");
    if (date < lo || date > hi) fail_("BAD_INPUT", "تاريخ الحصة خارج المدة المسموح بها.");
    const lastTopic = text_(p.lastTopic, 150, "الباب المشروح", false);

    let records = p.records;
    if (typeof records === "string") { try { records = JSON.parse(records); } catch (e) { records = []; } }
    if (!Array.isArray(records) || records.length === 0) fail_("BAD_INPUT", "لا توجد سجلات حضور لإرسالها.");
    if (records.length > CFG.MAX_ATT_RECORDS) fail_("BAD_INPUT", "عدد السجلات كبير جداً.");

    const roster = {};
    w.students.forEach(function (st) {
      if (st.codes.some(function (c) { return c.norm === course.normCode; })) roster[st.normName] = st.name;
    });
    const seen = {};
    const recs = records.map(function (r) {
      const nm = Array.isArray(r) ? r[0] : (r && r.studentName);
      const val = Array.isArray(r) ? r[1] : (r && r.value);
      const clean = text_(nm, 80, "اسم الطالب", true);
      const key = normName(clean);
      if (!roster[key]) fail_("BAD_INPUT", "الطالب «" + clean + "» غير مسجل في هذا الدرس. حدّث الصفحة وأعد المحاولة.");
      if (seen[key]) fail_("BAD_INPUT", "الطالب «" + clean + "» مكرر في القائمة.");
      seen[key] = true;
      return { key: key, name: roster[key], value: Number(val) === 1 ? 1 : 0 };
    });

    const attTbl = readTable_(ctx.ss, "attendance");
    const ai = attTbl.idx;
    const width = Math.max(ai.sessionId, ai.code, ai.date, ai.week, ai.month, ai.lastTopic, ai.student, ai.status, ai.value, ai.createdBy, ai.createdAt) + 1;
    const existing = {};
    for (let r = 1; r < attTbl.values.length; r++) {
      const row = attTbl.values[r];
      if (normCode(cleanVal(row[ai.code])) !== course.normCode) continue;
      if (toISODate_(row[ai.date]) !== date) continue;
      existing[normName(cleanVal(row[ai.student]))] = r + 1;
    }

    const now = fmtDate_(new Date(), "dd/MM/yyyy HH:mm:ss");
    const sessionId = course.code + "_" + date;
    const makeRow = function (rec) {
      const arr = new Array(width).fill("");
      arr[ai.sessionId] = sessionId;
      arr[ai.code] = course.code;
      arr[ai.date] = date;
      arr[ai.week] = isoWeek_(date);
      arr[ai.month] = parseInt(date.slice(5, 7), 10);
      arr[ai.lastTopic] = lastTopic;
      arr[ai.student] = rec.name;
      arr[ai.status] = rec.value === 1 ? "حاضر" : "غائب";
      arr[ai.value] = rec.value;
      arr[ai.createdBy] = user.name;
      arr[ai.createdAt] = now;
      return arr;
    };

    const sheet = attTbl.sheet;
    const toAppend = [];
    let updated = 0;
    recs.forEach(function (rec) {
      const rowNum = existing[rec.key];
      if (rowNum) {
        sheet.getRange(rowNum, 1, 1, width).setValues([makeRow(rec)]);
        updated++;
      } else {
        toAppend.push(makeRow(rec));
      }
    });
    if (toAppend.length) {
      const start = lastDataRow_(sheet, [ai.code + 1]) + 1;
      ensureRows_(sheet, start + toAppend.length - 1);
      sheet.getRange(start, 1, toAppend.length, width).setValues(toAppend);
    }

    if (CFG.SYNC_LAST_TOPIC_TO_COURSE && lastTopic && w.courseTbl.idx.lastTopic !== -1) {
      let latest = "";
      for (let r2 = 1; r2 < attTbl.values.length; r2++) {
        const rw = attTbl.values[r2];
        if (normCode(cleanVal(rw[ai.code])) === course.normCode) { const dd = toISODate_(rw[ai.date]); if (dd > latest) latest = dd; }
      }
      if (date >= latest) w.courseTbl.sheet.getRange(course.row, w.courseTbl.idx.lastTopic + 1).setValue(lastTopic);
    }

    removeNoSession_(ctx.ss, course.code, date);   // attendance recorded => the session did take place
    recordLog(ctx.ss, user.name, user.email, "تسجيل حضور", "الدرس: " + course.code + " | " + date + " | جديد: " + toAppend.length + " | محدّث: " + updated);
    return { success: true, message: "تم حفظ الحضور بنجاح", added: toAppend.length, updated: updated, sessionId: sessionId };
  });
}

function readStudentFields_(p, forCreate) {
  const out = {};
  if (forCreate || has_(p, "name")) {
    out.name = text_(p.name, 80, "اسم الطالب", true);
    if (out.name.length < 2) fail_("BAD_INPUT", "اسم الطالب قصير جداً.");
  }
  if (forCreate || has_(p, "category")) out.category = enum_(cleanVal(p.category) || "رجال", CFG.STUDENT_CATEGORIES, "الصنف");
  if (forCreate || has_(p, "ageGroup")) out.ageGroup = text_(normAge_(p.ageGroup), 10, "الفئة العمرية", false);
  if (forCreate || has_(p, "level")) {
    const lv = cleanVal(p.level) || "1";
    if (!/^\d{1,2}$/.test(lv)) fail_("BAD_INPUT", "المستوى غير صالح.");
    out.level = lv;
  }
  if (forCreate || has_(p, "city")) out.city = text_(p.city, 60, "الحي / المدينة", false);
  if (forCreate || has_(p, "location")) out.location = text_(p.location, 40, "المقر", false);
  if (forCreate || has_(p, "phone")) {
    const ph = cleanVal(p.phone);
    if (ph && !/^[0-9+ ]{6,20}$/.test(ph)) fail_("BAD_INPUT", "رقم الهاتف غير صالح.");
    out.phone = ph;
  }
  if (forCreate || has_(p, "completedBooks")) out.completedBooks = text_(p.completedBooks, 400, "الكتب المنجزة", false);
  return out;
}

function insertStudentRow_(ctx, w, f, codeOut) {
  const user = ctx.user;
  const sTbl = w.studentTbl, ix = sTbl.idx, sheet = sTbl.sheet;
  const id = nextStudentId_(w.students, archivedStudentIds_(ctx.ss));
  const now = fmtDate_(new Date(), "dd/MM/yyyy HH:mm:ss");
  const width = Math.max(ix.name, ix.category, ix.ageGroup, ix.level, ix.city, ix.location, ix.phone, ix.codes, ix.lastTeacher, ix.completedBooks) + 1;
  const row = new Array(width).fill("");
  row[ix.name] = f.name; row[ix.category] = f.category; row[ix.ageGroup] = f.ageGroup; row[ix.level] = f.level;
  row[ix.city] = f.city; row[ix.location] = f.location; row[ix.phone] = safeCell_(f.phone); row[ix.codes] = codeOut;
  row[ix.lastTeacher] = user.name; row[ix.completedBooks] = f.completedBooks;

  const target = lastDataRow_(sheet, [ix.name + 1]) + 1;
  ensureRows_(sheet, target);
  sheet.getRange(target, 1, 1, width).setValues([row]);
  sheet.getRange(target, ix.id + 1).setValue(id);
  sheet.getRange(target, ix.addedBy + 1).setValue(user.name);
  sheet.getRange(target, ix.addedAt + 1).setValue(now);
  return id;
}

function actionAddStudent_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const existingId = cleanVal(p.existingStudentId);
    const f = existingId ? null : readStudentFields_(p, true);   // joining an existing student needs no new details
    areaEnforce_(ctx.ss, f, "city");

    let codeOut = CFG.UNASSIGNED_CODE;
    const reqCode = cleanVal(p.courseCode);
    if (reqCode && !isUnassignedNorm(normCode(reqCode))) {
      const c = findCourse_(w, reqCode);
      if (!c) fail_("NOT_FOUND", "الدرس غير موجود.");
      if (!courseInScope_(c, w.scope)) fail_("FORBIDDEN", "لا يمكنك إضافة طالب إلى هذا الدرس.");
      codeOut = c.code;
    }

    if (existingId) {
      // the teacher decided it is the SAME person: just enrol him in the chosen course
      if (isUnassignedNorm(normCode(codeOut))) fail_("BAD_INPUT", "اختر الدرس الذي تريد إضافة الطالب إليه.");
      const ex = w.students.filter(function (s) { return s.id === existingId; })[0];
      if (!ex) fail_("NOT_FOUND", "الطالب المختار لم يعد موجوداً.");
      if (ex.codes.some(function (c) { return c.norm === normCode(codeOut); })) fail_("CONFLICT", "الطالب مسجل مسبقاً في هذا الدرس.");
      const merged = rebuildCodes_(ex, codeOut, normCode(codeOut));
      w.studentTbl.sheet.getRange(ex.row, w.studentTbl.idx.codes + 1).setValue(merged);
      recordLog(ctx.ss, user.name, user.email, "إضافة طالب موجود إلى درس", "ID: " + ex.id + " | الدرس: " + codeOut);
      return {
        success: true, message: "أُضيف الطالب الموجود إلى درسك", enrolledExisting: true,
        student: { id: ex.id, name: ex.name, category: ex.category, ageGroup: ex.ageGroup, level: ex.level, city: ex.city, location: ex.location, phone: ex.phone, courseCodes: merged, lastTeacher: ex.lastTeacher, completedBooks: ex.completedBooks, isUnassigned: false }
      };
    }
    if (!p.force) {
      const ms = findStudentMatches_(w.students, f);
      if (ms.length) fail_("DUPLICATE", "قد يكون هذا الطالب مسجلاً من قبل. اختر إن كان هو نفسه أو شخصاً آخر.", { matches: ms.map(function (m) { return maskedStudent_(m.st, m); }) });
    }

    const id = insertStudentRow_(ctx, w, f, codeOut);
    recordLog(ctx.ss, user.name, user.email, "إضافة طالب", "ID: " + id + " | الدرس: " + codeOut);
    return {
      success: true,
      message: "تمت إضافة الطالب بنجاح",
      student: {
        id: id, name: f.name, category: f.category, ageGroup: f.ageGroup, level: f.level, city: f.city,
        location: f.location, phone: f.phone, courseCodes: codeOut, lastTeacher: user.name,
        completedBooks: f.completedBooks, isUnassigned: isUnassignedNorm(normCode(codeOut))
      }
    };
  });
}

function actionUpdateStudent_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const id = text_(p.id, 20, "معرف الطالب", true);
    const st = w.students.filter(function (s) { return s.id === id; })[0];
    if (!st) fail_("NOT_FOUND", "لم يتم العثور على الطالب. حدّث الصفحة وأعد المحاولة.");
    if (!studentInScope_(st, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية تعديل هذا الطالب.");
    const f = readStudentFields_(p, false);
    areaEnforce_(ctx.ss, f, "city");
    let renamed = 0;
    if (has_(f, "name")) {
      if (normName(f.name) === normName(st.name)) delete f.name;      // unchanged: ignore
      else if (user.tier !== "T4") fail_("FORBIDDEN", "لا يمكن تعديل الاسم مباشرة. أرسل اقتراح تغيير الاسم إلى الإدارة.");
      else { renamed = renameStudent_(ctx, w, st, f.name); delete f.name; }
    }
    const ix = w.studentTbl.idx, sheet = w.studentTbl.sheet;
    const map = { name: ix.name, category: ix.category, ageGroup: ix.ageGroup, level: ix.level, city: ix.city, location: ix.location, phone: ix.phone, completedBooks: ix.completedBooks };
    const changed = [];
    Object.keys(f).forEach(function (k) {
      sheet.getRange(st.row, map[k] + 1).setValue(safeCell_(f[k]));
      changed.push(k);
    });
    recordLog(ctx.ss, user.name, user.email, "تحيين طالب", "ID: " + id + " | الحقول: " + changed.join(",") + (renamed ? " | إعادة تسمية (حضور: " + renamed + ")" : ""));
    return { success: true, message: "تم تحديث بيانات الطالب بنجاح" };
  });
}

/**
 * Move a student from one course to another. Both courses must belong to the caller
 * (T4 may move between any courses). Only the course-code cell of that student's row is touched.
 */
function actionMoveStudent_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const id = text_(p.studentId, 20, "معرف الطالب", true);
    const st = w.students.filter(function (s) { return s.id === id; })[0];
    if (!st) fail_("NOT_FOUND", "لم يتم العثور على الطالب. حدّث الصفحة وأعد المحاولة.");
    if (!studentInScope_(st, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية على هذا الطالب.");

    const from = findCourse_(w, p.fromCode);
    const to = findCourse_(w, p.toCode);
    if (!from || !to) fail_("NOT_FOUND", "الدرس غير موجود.");
    if (from.normCode === to.normCode) fail_("BAD_INPUT", "اختر درساً مختلفاً.");
    const mine = function (c) { return !!(c.owner && c.owner.row === user.row) || user.tier === "T4"; };
    if (!mine(from) || !mine(to)) fail_("FORBIDDEN", "يمكنك نقل الطالب بين دروسك فقط.");
    if (!st.codes.some(function (c) { return c.norm === from.normCode; })) {
      fail_("BAD_INPUT", "الطالب غير مسجل في الدرس الأصلي. حدّث الصفحة وأعد المحاولة.");
    }

    // rebuild the code cell: replace the old code, drop "no course" placeholders, no duplicates
    const raw = String(st.codesStr || "").split(/[,،;\r\n\/]+/).map(function (s) { return s.trim(); }).filter(Boolean);
    const out = [], seen = {};
    raw.forEach(function (tok) {
      let n = normCode(tok);
      if (n === from.normCode) { tok = to.code; n = to.normCode; }
      else if (isUnassignedNorm(n)) return;
      if (seen[n]) return;
      seen[n] = true; out.push(tok);
    });
    if (!seen[to.normCode]) out.push(to.code);
    const cell = out.join(", ");

    w.studentTbl.sheet.getRange(st.row, w.studentTbl.idx.codes + 1).setValue(cell);
    recordLog(ctx.ss, user.name, user.email, "نقل طالب", "ID: " + id + " | من: " + from.code + " | إلى: " + to.code);
    return { success: true, message: "تم نقل الطالب بنجاح", courseCodes: cell };
  });
}

/** v67: a course held at a home keeps the home's place (a name from the areas list, no free text). */
function readCourseHome_(ss, p, f, current) {
  const place = f.place !== undefined ? f.place : (current ? current.place : "");
  if (place !== "بيت") { if (f.place !== undefined || has_(p, "home")) f.home = ""; return; }
  const h = { home: text_(p.home !== undefined ? p.home : (current ? current.home : ""), 60, "عنوان البيت", false) };
  if (!h.home) fail_("BAD_INPUT", "اكتب عنوان البيت (من القائمة).");
  areaEnforce_(ss, h, "home", "تونس");
  f.home = h.home;
}
/** Adds an optional column to the courses tab the first time it is needed («عنوان البيت», «حالة الدرس», «سبب التوقف»). */
function courseCol_(tb, key, header) {
  if (tb.idx[key] !== undefined && tb.idx[key] !== -1) return tb.idx[key];
  const sh = tb.sheet, last = Math.max(1, sh.getLastColumn());
  sh.getRange(1, last + 1).setValue(header);
  tb.idx[key] = last;
  return last;
}
function courseHomeCol_(tb) { return courseCol_(tb, "home", "عنوان البيت"); }
/** v67: a course's declared state; a stopped course needs its reason. */
function readCourseStatus_(p, f, current) {
  if (!has_(p, "status") && !has_(p, "stopReason")) return;
  const status = has_(p, "status") ? enum_(cleanVal(p.status) || "نشط", CFG.COURSE_STATUS, "حالة الدرس") : (current ? current.status : "نشط");
  f.status = status;
  if (status === "متوقف") {
    const why = cleanVal(has_(p, "stopReason") ? p.stopReason : (current ? current.stopReason : ""));
    if (!why) fail_("BAD_INPUT", "اختر سبب توقف الدرس.");
    f.stopReason = enum_(why, CFG.STOP_REASONS, "سبب التوقف");
  } else f.stopReason = "";
}

function readCourseFields_(p, w, forCreate) {
  const out = {};
  if (forCreate || has_(p, "category")) {
    const cats = extractListOptions_(w.courseTbl.sheet, w.courseTbl.idx.category, false);
    out.category = cats.length ? enum_(p.category, cats, "صنف الدرس") : text_(p.category, 40, "صنف الدرس", true);
  }
  if (forCreate || has_(p, "day")) out.day = enum_(p.day, CFG.WEEK_DAYS, "اليوم");
  if (forCreate || has_(p, "timing")) out.time = timeVal_(p.timing);
  if (forCreate || has_(p, "location")) out.place = enum_(p.location, CFG.PLACES, "مكان الدرس");
  if (forCreate || has_(p, "venue")) out.venue = text_(p.venue, 40, "المقر", false);
  if (forCreate || has_(p, "book")) out.book = text_(p.book, 80, "الكتاب", true);
  return out;
}

function actionCreateCourse_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, false);
    let owner = user;
    const targetEmail = cleanVal(p.teacherEmail).toLowerCase();
    if (targetEmail && targetEmail !== user.email) {
      const t = findStaffByEmail_(ctx.staff, targetEmail);
      if (!t) fail_("NOT_FOUND", "المدرس غير موجود.");
      if (!(user.tier === "T4" || w.scope.superviseeRows[t.row])) fail_("FORBIDDEN", "لا يمكنك فتح درس لهذا المدرس.");
      owner = t;
    }
    if (!owner.prefix) fail_("BAD_INPUT", "لا يوجد رمز (prefix) لهذا المدرس في جدول المدرسين.");
    const f = readCourseFields_(p, w, true);
    readCourseHome_(ctx.ss, p, f, null);

    let max = 0;
    w.courses.forEach(function (c) {
      if (c.codeInfo && c.codeInfo.prefix === owner.normPrefix) max = Math.max(max, c.codeInfo.num);
    });
    const code = __genId("course:" + owner.prefix, owner.prefix + "-" + (max + 1));
    if (w.courses.some(function (c) { return c.normCode === normCode(code); })) fail_("CONFLICT", "تعذر توليد رمز الدرس، أعد المحاولة.");

    const tb = w.courseTbl, ix = tb.idx, sheet = tb.sheet;
    const width = Math.max(ix.teacher, ix.category, ix.code, ix.day, ix.time, ix.place, ix.venue, ix.book) + 1;
    const row = new Array(width).fill("");
    row[ix.teacher] = owner.name; row[ix.category] = f.category; row[ix.code] = code; row[ix.day] = f.day;
    row[ix.time] = f.time; row[ix.place] = f.place; row[ix.venue] = f.venue; row[ix.book] = f.book;

    const prev = lastDataRow_(sheet, [ix.code + 1, ix.teacher + 1]);
    const target = prev + 1;
    ensureRows_(sheet, target);
    sheet.getRange(target, 1, 1, width).setValues([row]);
    if (f.home) sheet.getRange(target, courseHomeCol_(tb) + 1).setValue(f.home);
    if (ix.addedBy !== -1) sheet.getRange(target, ix.addedBy + 1).setValue(user.name);
    if (ix.createdAt !== -1) sheet.getRange(target, ix.createdAt + 1).setValue(fmtDate_(new Date(), "yyyy-MM-dd HH:mm:ss"));
    copyRowSupport_(sheet, prev, target, ix);

    recordLog(ctx.ss, user.name, user.email, "فتح درس", "الرمز: " + code + " | المدرس: " + owner.name + " | الكتاب: " + f.book);
    return {
      success: true,
      message: "تم فتح الدرس بنجاح",
      course: {
        code: code, teacher: owner.name, teacherTier: owner.tier, supervisor: owner.supervisorRaw,
        book: f.book, day: f.day, timing: f.time, location: f.place, home: f.home || "", venue: f.venue, category: f.category,
        isOwnCourse: owner.row === user.row
      }
    };
  });
}

/** Keeps formulas (progress / student count) and formatting consistent on a freshly added course row. */
function copyRowSupport_(sheet, prevRow, newRow, ix) {
  try {
    if (prevRow < 2) return;
    ["progress", "count"].forEach(function (f) {
      const i = ix[f];
      if (i === -1) return;
      const dest = sheet.getRange(newRow, i + 1);
      if (dest.getFormula()) return;
      const src = sheet.getRange(prevRow, i + 1);
      if (src.getFormula()) src.copyTo(dest, SpreadsheetApp.CopyPasteType.PASTE_FORMULA, false);
    });
    const lastCol = sheet.getLastColumn();
    const src2 = sheet.getRange(prevRow, 1, 1, lastCol);
    const dst2 = sheet.getRange(newRow, 1, 1, lastCol);
    src2.copyTo(dst2, SpreadsheetApp.CopyPasteType.PASTE_FORMAT, false);
    src2.copyTo(dst2, SpreadsheetApp.CopyPasteType.PASTE_DATA_VALIDATION, false);
  } catch (e) {
    Logger.log("copyRowSupport_: " + e);
  }
}

function actionUpdateCourse_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, false);
    const course = findCourse_(w, p.code);
    if (!course) fail_("NOT_FOUND", "لم يتم العثور على الدرس.");
    if (!courseInScope_(course, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية تعديل هذا الدرس.");
    const f = readCourseFields_(p, w, false);
    readCourseHome_(ctx.ss, p, f, course);
    readCourseStatus_(p, f, course);
    const ix = w.courseTbl.idx, sheet = w.courseTbl.sheet;
    if (f.home !== undefined && (f.home || (ix.home !== undefined && ix.home !== -1))) courseHomeCol_(w.courseTbl);
    else delete f.home;
    if (f.status !== undefined) { courseCol_(w.courseTbl, "status", "حالة الدرس"); courseCol_(w.courseTbl, "stopReason", "سبب التوقف"); }
    const map = { category: ix.category, day: ix.day, time: ix.time, place: ix.place, venue: ix.venue, book: ix.book, home: ix.home, status: ix.status, stopReason: ix.stopReason };
    const changed = [];
    Object.keys(f).forEach(function (k) {
      sheet.getRange(course.row, map[k] + 1).setValue(f[k]);
      changed.push(k);
    });
    if (!changed.length) fail_("BAD_INPUT", "لا توجد تعديلات لحفظها.");
    recordLog(ctx.ss, user.name, user.email, "تعديل درس", "الدرس: " + course.code + " | الحقول: " + changed.join(",") + (f.status !== undefined ? " | الحالة: " + f.status + (f.stopReason ? " (" + f.stopReason + ")" : "") : ""));
    return { success: true, message: "تم تحديث بيانات الدرس بنجاح" };
  });
}

function actionLogFollowUp_(ctx, p) {
  const user = ctx.user;
  const w = loadWorld_(ctx, true);
  const id = text_(p.studentId, 20, "معرف الطالب", true);
  const st = w.students.filter(function (s) { return s.id === id; })[0];
  if (!st) fail_("NOT_FOUND", "لم يتم العثور على الطالب.");
  if (!studentInScope_(st, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية على هذا الطالب.");
  const code = text_(p.courseCode, 60, "رمز الدرس", false);
  recordLog(ctx.ss, user.name, user.email, "متابعة غياب", "الطالب: " + st.name + " | ID: " + id + (code ? " | الدرس: " + code : ""));
  return { success: true, message: "تم تسجيل التواصل بنجاح" };
}

/* ===================== PHASE 1: DELETION REQUESTS / NO-SESSION / FEED ===================== */

const SHEETS_P1 = {
  DELETE_REQ: { name: "طلبات الحذف", headers: ["معرف الطلب", "تاريخ الطلب", "معرف الطالب", "اسم الطالب", "صاحب الطلب", "بريده", "سبب الحذف", "الحالة", "القرار بواسطة", "تاريخ القرار", "ملاحظة", "رمز الدرس"] },
  NAME_REQ: { name: "اقتراحات الأسماء", headers: ["معرف الاقتراح", "تاريخ الاقتراح", "معرف الطالب", "الاسم الحالي", "الاسم المقترح", "صاحب الاقتراح", "بريده", "السبب", "الحالة", "القرار بواسطة", "تاريخ القرار", "ملاحظة", "الاسم المعتمد"] },
  DELETED: { name: "الطلاب المحذوفون", headers: ["تاريخ الحذف", "حُذف بواسطة", "سبب الحذف", "صاحب الطلب", "معرف الطلب", "معرف الطالب"] },
  NO_SESSION: { name: "دروس لم تنعقد", headers: ["المفتاح", "رمز الدرس", "التاريخ", "السبب", "التفاصيل", "سجّل بواسطة", "وقت التسجيل"] }
};
const DR_PENDING = "قيد المراجعة", DR_APPROVED = "تمت الموافقة", DR_REJECTED = "مرفوض";
const NO_SESSION_REASONS = ["أعياد", "ظرف طارئ", "غياب المدرس", "ظروف الطلبة"];
const FEED_DAYS = 30, FEED_MAX = 60;

function safeCell_(v) {
  if (typeof v !== "string") return v;
  const s = v.slice(0, 500);
  return /^[=+\-@]/.test(s) ? "'" + s : s;
}

function colLetter_(n) { let s = ""; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }

function p1Sheet_(ss, def, create) {
  let sh = ss.getSheetByName(def.name);
  if (!sh && create) {
    sh = ss.insertSheet(def.name);
    try { sh.getRange("A:" + colLetter_(def.headers.length)).setNumberFormat("@"); } catch (e) { /* plain text: stops Sheets turning dates/ids into other types */ }
    sh.getRange(1, 1, 1, def.headers.length).setValues([def.headers]);
    try { sh.setRightToLeft(true); } catch (e) { /* cosmetic */ }
  }
  return sh;
}

function stampStr_(v) { return v instanceof Date ? fmtDate_(v, "yyyy-MM-dd HH:mm") : cleanVal(v); }

function nowStamp_() { return fmtDate_(new Date(), "yyyy-MM-dd HH:mm"); }

function p1Rows_(sh, width) {
  if (!sh || sh.getLastRow() < 2) return [];
  return sh.getRange(2, 1, sh.getLastRow() - 1, width).getValues();
}

/** Used student ids INCLUDING already-deleted ones, so an id is never reused. */
function archivedStudentIds_(ss) {
  const sh = p1Sheet_(ss, SHEETS_P1.DELETED, false), used = {};
  p1Rows_(sh, 6).forEach(function (r) { const id = cleanVal(r[5]); if (id) used[id] = true; });
  return used;
}

/* ------------------------------ deletion requests ------------------------------ */

/** The deletion sheet gained a "course code" column (L); add it to sheets created before that. */
function drSheet_(ss, create) {
  const sh = p1Sheet_(ss, SHEETS_P1.DELETE_REQ, create);
  if (sh) {
    const h = sh.getRange(1, 1, 1, Math.max(sh.getLastColumn(), 1)).getValues()[0];
    if (!cleanVal(h[11])) sh.getRange(1, 12).setValue("رمز الدرس");
  }
  return sh;
}

function removeCodeFromCodes_(st, courseNorm) {
  const raw = String(st.codesStr || "").split(/[,،;\r\n\/]+/).map(function (s) { return s.trim(); }).filter(Boolean);
  const out = [];
  raw.forEach(function (tok) { const n = normCode(tok); if (isUnassignedNorm(n) || n === courseNorm) return; out.push(tok); });
  return out.join(", ");
}

function actionRequestDeletion_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const id = text_(p.studentId, 40, "معرف الطالب", true);
    const st = w.students.filter(function (s) { return s.id === id; })[0];
    if (!st) fail_("NOT_FOUND", "لم يتم العثور على الطالب.");
    if (!studentInScope_(st, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية على هذا الطالب.");
    const course = findCourse_(w, p.courseCode);
    if (!course || isUnassignedNorm(course.normCode)) fail_("BAD_INPUT", "اختر الدرس الذي تريد حذف الطالب منه.");
    if (!courseInScope_(course, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية على هذا الدرس.");
    if (!st.codes.some(function (c) { return c.norm === course.normCode; })) fail_("BAD_INPUT", "الطالب غير مسجل في هذا الدرس.");
    const reason = text_(p.reason, 200, "سبب الحذف", true);
    if (reason.length < 3) fail_("BAD_INPUT", "يرجى كتابة سبب الحذف.");

    const sh = drSheet_(ctx.ss, true);
    const rows = p1Rows_(sh, 12);
    let max = 0;
    rows.forEach(function (r) {
      const m = /^DR-(\d+)$/.exec(cleanVal(r[0])); if (m) max = Math.max(max, parseInt(m[1], 10));
      if (cleanVal(r[2]) === id && cleanVal(r[7]) === DR_PENDING && normCode(cleanVal(r[11])) === course.normCode) fail_("CONFLICT", "يوجد طلب حذف قيد المراجعة لهذا الطالب في هذا الدرس.");
    });
    const reqId = __genId("DR", "DR-" + ("0000" + (max + 1)).slice(-4));
    sh.getRange(sh.getLastRow() + 1, 1, 1, 12).setValues([[reqId, nowStamp_(), id, safeCell_(st.name), safeCell_(user.name), safeCell_(user.email), safeCell_(reason), DR_PENDING, "", "", "", safeCell_(course.code)]]);
    recordLog(ctx.ss, user.name, user.email, "طلب حذف طالب من درس", "ID: " + id + " | الدرس: " + course.code + " | الطلب: " + reqId);
    return { success: true, message: "تم إرسال طلب الحذف إلى الإدارة", request: { id: reqId, studentId: id, courseCode: course.code, status: DR_PENDING } };
  });
}

/**
 * Approving removes the student from THAT course only. If no other course remains the student
 * becomes "no course" and "last teacher" is set to the requester so he can still see him.
 */
function actionDecideDeletion_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    if (user.tier !== "T4") fail_("FORBIDDEN", "الموافقة على الحذف للمدير فقط.");
    const reqId = text_(p.requestId, 20, "معرف الطلب", true);
    const decision = cleanVal(p.decision);
    if (decision !== "approve" && decision !== "reject") fail_("BAD_INPUT", "قرار غير صالح.");
    const note = text_(p.note, 200, "الملاحظة", decision === "reject");

    const sh = drSheet_(ctx.ss, false);
    if (!sh) fail_("NOT_FOUND", "لا توجد طلبات حذف.");
    const rows = p1Rows_(sh, 12);
    let rowNum = -1, req = null;
    rows.forEach(function (r, i) { if (cleanVal(r[0]) === reqId) { rowNum = i + 2; req = r; } });
    if (!req) fail_("NOT_FOUND", "الطلب غير موجود.");
    if (cleanVal(req[7]) !== DR_PENDING) fail_("CONFLICT", "تم البت في هذا الطلب مسبقاً.");

    if (decision === "approve") {
      const courseCode = cleanVal(req[11]);
      if (!courseCode) fail_("BAD_INPUT", "طلب قديم لا يحدد الدرس. ارفضه واطلب من المدرس إرسال طلب جديد.");
      const w = loadWorld_(ctx, true);
      const sid = cleanVal(req[2]);
      const st = w.students.filter(function (s) { return s.id === sid; })[0];
      if (!st) fail_("NOT_FOUND", "الطالب لم يعد موجوداً في الجدول. ارفض الطلب مع ملاحظة.");
      const cn = normCode(courseCode);
      if (!st.codes.some(function (c) { return c.norm === cn; })) fail_("CONFLICT", "الطالب لم يعد مسجلاً في هذا الدرس. ارفض الطلب مع ملاحظة.");
      const left = removeCodeFromCodes_(st, cn);
      const ix = w.studentTbl.idx, ssh = w.studentTbl.sheet;
      const becameUnassigned = !left;
      ssh.getRange(st.row, ix.codes + 1).setValue(becameUnassigned ? CFG.UNASSIGNED_CODE : left);
      if (becameUnassigned) ssh.getRange(st.row, ix.lastTeacher + 1).setValue(safeCell_(cleanVal(req[4])));
      sh.getRange(rowNum, 8, 1, 4).setValues([[DR_APPROVED, safeCell_(user.name), nowStamp_(), safeCell_(note)]]);
      recordLog(ctx.ss, user.name, user.email, "حذف طالب من درس (موافقة)", "ID: " + sid + " | الدرس: " + courseCode + " | الطلب: " + reqId);
      return { success: true, message: becameUnassigned ? "أُزيل الطالب من الدرس وأصبح «بلا درس»" : "أُزيل الطالب من هذا الدرس فقط", studentId: sid, courseCode: courseCode, codes: becameUnassigned ? CFG.UNASSIGNED_CODE : left, unassigned: becameUnassigned, status: DR_APPROVED };
    }
    sh.getRange(rowNum, 8, 1, 4).setValues([[DR_REJECTED, safeCell_(user.name), nowStamp_(), safeCell_(note)]]);
    recordLog(ctx.ss, user.name, user.email, "رفض طلب حذف", "الطلب: " + reqId);
    return { success: true, message: "تم رفض الطلب", studentId: cleanVal(req[2]), status: DR_REJECTED };
  });
}

/* ------------------------------ name changes: suggestion -> T4 decision ------------------------------ */

/** Rename a student in الرواد AND in the attendance rows of his courses (attendance is linked by name). */
function renameStudent_(ctx, w, st, newName) {
  const oldKey = normName(st.name);
  w.studentTbl.sheet.getRange(st.row, w.studentTbl.idx.name + 1).setValue(newName);
  const attTbl = readTable_(ctx.ss, "attendance");
  const ai = attTbl.idx, sheet = attTbl.sheet;
  const mine = {};
  st.codes.forEach(function (c) { mine[c.norm] = true; });
  let n = 0;
  for (let r = 1; r < attTbl.values.length; r++) {
    const row = attTbl.values[r];
    if (normName(cleanVal(row[ai.student])) === oldKey && mine[normCode(cleanVal(row[ai.code]))]) {
      sheet.getRange(r + 1, ai.student + 1).setValue(newName);
      n++;
    }
  }
  return n;
}

function actionSuggestNameChange_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, true);
    const id = text_(p.studentId, 40, "معرف الطالب", true);
    const st = w.students.filter(function (s) { return s.id === id; })[0];
    if (!st) fail_("NOT_FOUND", "لم يتم العثور على الطالب.");
    if (!studentInScope_(st, w.scope)) fail_("FORBIDDEN", "لا تملك صلاحية على هذا الطالب.");
    const nn = text_(p.newName, 80, "الاسم المقترح", true);
    if (nn.length < 2) fail_("BAD_INPUT", "الاسم المقترح قصير جداً.");
    if (normName(nn) === normName(st.name)) fail_("BAD_INPUT", "الاسم المقترح مطابق للحالي.");
    const reason = text_(p.reason, 200, "السبب", false);

    const sh = p1Sheet_(ctx.ss, SHEETS_P1.NAME_REQ, true);
    const rows = p1Rows_(sh, 13);
    let max = 0;
    rows.forEach(function (r) {
      const m = /^NC-(\d+)$/.exec(cleanVal(r[0])); if (m) max = Math.max(max, parseInt(m[1], 10));
      if (cleanVal(r[2]) === id && cleanVal(r[8]) === DR_PENDING) fail_("CONFLICT", "يوجد اقتراح اسم قيد المراجعة لهذا الطالب.");
    });
    const reqId = __genId("NC", "NC-" + ("0000" + (max + 1)).slice(-4));
    sh.getRange(sh.getLastRow() + 1, 1, 1, 13).setValues([[reqId, nowStamp_(), id, safeCell_(st.name), safeCell_(nn), safeCell_(user.name), safeCell_(user.email), safeCell_(reason), DR_PENDING, "", "", "", ""]]);
    recordLog(ctx.ss, user.name, user.email, "اقتراح تغيير اسم", "ID: " + id + " | الاقتراح: " + reqId);
    return { success: true, message: "تم إرسال اقتراح الاسم إلى الإدارة", request: { id: reqId, studentId: id, status: DR_PENDING } };
  });
}

function actionDecideNameChange_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    if (user.tier !== "T4") fail_("FORBIDDEN", "اعتماد الأسماء للمدير فقط.");
    const reqId = text_(p.requestId, 20, "معرف الاقتراح", true);
    const decision = cleanVal(p.decision);
    if (decision !== "approve" && decision !== "reject") fail_("BAD_INPUT", "قرار غير صالح.");
    const note = text_(p.note, 200, "الملاحظة", decision === "reject");
    const sh = p1Sheet_(ctx.ss, SHEETS_P1.NAME_REQ, false);
    if (!sh) fail_("NOT_FOUND", "لا توجد اقتراحات.");
    const rows = p1Rows_(sh, 13);
    let rowNum = -1, req = null;
    rows.forEach(function (r, i) { if (cleanVal(r[0]) === reqId) { rowNum = i + 2; req = r; } });
    if (!req) fail_("NOT_FOUND", "الاقتراح غير موجود.");
    if (cleanVal(req[8]) !== DR_PENDING) fail_("CONFLICT", "تم البت في هذا الاقتراح مسبقاً.");

    if (decision === "approve") {
      const finalName = has_(p, "finalName") && cleanVal(p.finalName) ? text_(p.finalName, 80, "الاسم المعتمد", true) : cleanVal(req[4]);
      if (finalName.length < 2) fail_("BAD_INPUT", "الاسم قصير جداً.");
      const w = loadWorld_(ctx, true);
      const sid = cleanVal(req[2]);
      const st = w.students.filter(function (s) { return s.id === sid; })[0];
      if (!st) fail_("NOT_FOUND", "الطالب لم يعد موجوداً. ارفض الاقتراح مع ملاحظة.");
      const updated = renameStudent_(ctx, w, st, finalName);
      sh.getRange(rowNum, 9, 1, 5).setValues([[DR_APPROVED, safeCell_(user.name), nowStamp_(), safeCell_(note), safeCell_(finalName)]]);
      recordLog(ctx.ss, user.name, user.email, "اعتماد تغيير اسم", "ID: " + sid + " | من: " + st.name + " | إلى: " + finalName + " | سجلات الحضور: " + updated);
      return { success: true, message: "تم اعتماد الاسم الجديد", studentId: sid, name: finalName, attendanceUpdated: updated, status: DR_APPROVED };
    }
    sh.getRange(rowNum, 9, 1, 4).setValues([[DR_REJECTED, safeCell_(user.name), nowStamp_(), safeCell_(note)]]);
    recordLog(ctx.ss, user.name, user.email, "رفض اقتراح اسم", "الاقتراح: " + reqId);
    return { success: true, message: "تم رفض الاقتراح", studentId: cleanVal(req[2]), status: DR_REJECTED };
  });
}

/* ------------------------------ v68: approval on the spot (offline app only) ------------------------------ */
/**
 * A teacher and the T4 meet: the teacher's phone shows its request as a QR code signed by that phone, the T4's
 * phone shows its decision as a QR code signed by the T4's phone. The station checks both signatures, then runs
 * this action as the teacher, with the T4 as the one who decides: the request is recorded and decided at once.
 * The approver comes only from the offline engine (never from the request itself): Apps Script refuses it.
 *   kind "deletion": studentId, courseCode, reason      kind "name": studentId, newName, reason, finalName
 *   decision "approve" | "reject", note (required when rejecting)
 */
function spotApprover_() { try { return typeof __spotApprover === "function" ? __spotApprover() : null; } catch (e) { return null; } }

function actionSpotDecision_(ctx, p) {
  const ap = spotApprover_();
  if (!ap || !ap.email) fail_("FORBIDDEN", "الاعتماد الفوري يتم عبر تطبيق الهاتف فقط.");
  const em = String(ap.email).toLowerCase();
  let dec = (ctx.staff || []).filter(function (s) { return s.email && String(s.email).toLowerCase() === em; })[0] || null;
  // on a phone the T4 may not be in the local list: the phone checked the T4's signature against the station's list
  if (!dec && ap.tier && ap.name) dec = { name: ap.name, email: em, tier: ap.tier, row: -1 };
  if (!dec || dec.tier !== "T4") fail_("FORBIDDEN", "المعتمِد ليس من المديرين (T4).");
  if (ctx.user && String(ctx.user.email || "").toLowerCase() === em) fail_("BAD_INPUT", "لا يعتمد المدير طلبه بنفسه.");
  const kind = cleanVal(p.kind), decision = cleanVal(p.decision);
  if (decision !== "approve" && decision !== "reject") fail_("BAD_INPUT", "قرار غير صالح.");
  const ctxT4 = Object.assign({}, ctx, { user: dec });
  if (kind === "deletion") {
    const r1 = actionRequestDeletion_(ctx, { studentId: p.studentId, courseCode: p.courseCode, reason: p.reason });
    const r2 = actionDecideDeletion_(ctxT4, { requestId: r1.request.id, decision: decision, note: p.note });
    return Object.assign({}, r2, { success: true, kind: kind, requestId: r1.request.id, decision: decision, decidedBy: dec.name, spot: true });
  }
  if (kind === "name") {
    const r1 = actionSuggestNameChange_(ctx, { studentId: p.studentId, newName: p.newName, reason: p.reason });
    const r2 = actionDecideNameChange_(ctxT4, { requestId: r1.request.id, decision: decision, note: p.note, finalName: p.finalName });
    return Object.assign({}, r2, { success: true, kind: kind, requestId: r1.request.id, decision: decision, decidedBy: dec.name, spot: true });
  }
  fail_("BAD_INPUT", "نوع طلب غير معروف.");
}

/* ------------------------------ session did not take place ------------------------------ */

function noSessionKey_(code, date) { return normCode(code) + "_" + date; }

function removeNoSession_(ss, courseCode, date) {
  const sh = p1Sheet_(ss, SHEETS_P1.NO_SESSION, false);
  if (!sh) return false;
  const key = noSessionKey_(courseCode, date);
  const rows = p1Rows_(sh, 7);
  for (let i = rows.length - 1; i >= 0; i--) {
    if (noSessionKey_(cleanVal(rows[i][1]), toISODate_(rows[i][2])) === key) { sh.deleteRow(i + 2); return true; }
  }
  return false;
}

function checkSessionDate_(p) {
  const date = cleanVal(p.date);
  if (!validISODate_(date)) fail_("BAD_INPUT", "تاريخ الحصة غير صالح.");
  const lo = fmtDate_(new Date(Date.now() - 370 * 86400000), "yyyy-MM-dd");
  const hi = fmtDate_(new Date(Date.now() + 86400000), "yyyy-MM-dd");
  if (date < lo || date > hi) fail_("BAD_INPUT", "تاريخ الحصة خارج المدة المسموح بها.");
  return date;
}

function ownCourseOrAdmin_(ctx, w, code) {
  const course = findCourse_(w, code);
  if (!course) fail_("NOT_FOUND", "الدرس غير موجود.");
  const isOwn = !!(course.owner && course.owner.row === ctx.user.row);
  if (!(isOwn || ctx.user.tier === "T4")) fail_("FORBIDDEN", "يمكنك تعديل حصص دروسك فقط.");
  return course;
}

function actionMarkNoSession_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const w = loadWorld_(ctx, false);
    const course = ownCourseOrAdmin_(ctx, w, p.courseCode);
    const date = checkSessionDate_(p);
    const reason = enum_(cleanVal(p.reason), NO_SESSION_REASONS, "السبب");
    const details = "";   // no free text: the reason comes from the fixed list

    const attTbl = readTable_(ctx.ss, "attendance");
    const ai = attTbl.idx;
    for (let r = 1; r < attTbl.values.length; r++) {
      const row = attTbl.values[r];
      if (normCode(cleanVal(row[ai.code])) === course.normCode && toISODate_(row[ai.date]) === date) {
        fail_("CONFLICT", "تم تسجيل حضور في هذا اليوم، لا يمكن اعتباره حصة لم تنعقد.");
      }
    }
    removeNoSession_(ctx.ss, course.code, date);   // upsert
    const sh = p1Sheet_(ctx.ss, SHEETS_P1.NO_SESSION, true);
    sh.getRange(sh.getLastRow() + 1, 1, 1, 7).setValues([[noSessionKey_(course.code, date), course.code, date, reason, safeCell_(details), safeCell_(user.name), nowStamp_()]]);
    recordLog(ctx.ss, user.name, user.email, "حصة لم تنعقد", "الدرس: " + course.code + " | " + date + " | " + reason);
    return { success: true, message: "تم تسجيل أن الحصة لم تنعقد", noSession: { courseCode: course.code, date: date, reason: reason, details: details, by: user.name } };
  });
}

function actionClearNoSession_(ctx, p) {
  return withLock_(function () {
    const w = loadWorld_(ctx, false);
    const course = ownCourseOrAdmin_(ctx, w, p.courseCode);
    const date = checkSessionDate_(p);
    const removed = removeNoSession_(ctx.ss, course.code, date);
    if (removed) recordLog(ctx.ss, ctx.user.name, ctx.user.email, "إلغاء «حصة لم تنعقد»", "الدرس: " + course.code + " | " + date);
    return { success: true, removed: removed };
  });
}

/* ------------------------------ feed + read models ------------------------------ */

function seenKey_(email) { return "seen:" + email; }

function actionMarkFeedSeen_(ctx) {
  PropertiesService.getScriptProperties().setProperty(seenKey_(ctx.user.email), nowStamp_());
  return { success: true };
}

/** Rows to read from a P1 sheet: never beyond the columns it actually has. */
function p1Width_(ss, def, want) {
  const sh = ss.getSheetByName(def.name);
  return sh ? Math.min(want, sh.getLastColumn()) : want;
}

function buildPhase1Data_(ctx, courses, courseTbl, scope) {
  const ss = ctx.ss, user = ctx.user;
  const out = { noSessions: [], myDeletionRequests: [], deletionInbox: [], nameInbox: [], myNameSuggestions: [], feed: [], feedUnread: 0, noSessionReasons: NO_SESSION_REASONS.slice() };
  const cutoffD = new Date(); cutoffD.setMonth(cutoffD.getMonth() - CFG.ATTENDANCE_MONTHS);
  const cutoff = fmtDate_(cutoffD, "yyyy-MM-dd");
  const feedCut = fmtDate_(new Date(Date.now() - FEED_DAYS * 86400000), "yyyy-MM-dd HH:mm");
  const isSup = user.rank >= 3;      // T3, T4
  const feed = [];

  p1Rows_(p1Sheet_(ss, SHEETS_P1.NO_SESSION, false), 7).forEach(function (r) {
    const code = cleanVal(r[1]), date = toISODate_(r[2]);
    if (!code || !date) return;
    if (!scope.isAdmin && !scope.allowedCodes[normCode(code)]) return;
    if (date >= cutoff) out.noSessions.push({ courseCode: code, date: date, reason: cleanVal(r[3]), details: cleanVal(r[4]), by: cleanVal(r[5]) });
    const at = stampStr_(r[6]);
    if (isSup && at >= feedCut && cleanVal(r[5]) !== user.name) feed.push({ type: "no_session", at: at, text: cleanVal(r[5]) + ": الدرس " + code + " لم ينعقد يوم " + date + " (" + cleanVal(r[3]) + ")" });
  });

  if (isSup && courseTbl.idx.createdAt !== -1) {
    const ci = courseTbl.idx;
    courses.forEach(function (c) {
      if (!scope.isAdmin && !scope.allowedCodes[c.normCode]) return;
      const disp = courseTbl.display[c.row - 1] || [];
      const at = cleanVal(disp[ci.createdAt]).slice(0, 16);
      const by = ci.addedBy !== -1 ? cleanVal(disp[ci.addedBy]) : "";
      if (at && at >= feedCut && by !== user.name) feed.push({ type: "new_course", at: at, text: (by || "—") + " فتح درساً جديداً: " + c.code + " (" + (c.owner ? c.owner.name : c.teacherRaw) + ")" });
    });
  }

  const dr = p1Rows_(p1Sheet_(ss, SHEETS_P1.DELETE_REQ, false), p1Width_(ss, SHEETS_P1.DELETE_REQ, 12));
  dr.forEach(function (r) {
    const item = { id: cleanVal(r[0]), at: stampStr_(r[1]).slice(0, 16), studentId: cleanVal(r[2]), studentName: cleanVal(r[3]), by: cleanVal(r[4]), reason: cleanVal(r[6]), status: cleanVal(r[7]), decidedBy: cleanVal(r[8]), note: cleanVal(r[10]), courseCode: cleanVal(r[11]) };
    if (cleanVal(r[5]).toLowerCase() === user.email && item.status === DR_PENDING) out.myDeletionRequests.push({ id: item.id, studentId: item.studentId, courseCode: item.courseCode, status: item.status });
    if (user.tier === "T4") {
      if (item.status === DR_PENDING) out.deletionInbox.push(item);
      if (item.at >= feedCut && item.by !== user.name) feed.push({ type: "deletion_request", at: item.at, text: item.by + " طلب حذف الطالب «" + item.studentName + "»" + (item.courseCode ? " من الدرس " + item.courseCode : "") + (item.status === DR_PENDING ? "" : " — " + item.status) });
    }
  });

  p1Rows_(p1Sheet_(ss, SHEETS_P1.NAME_REQ, false), 13).forEach(function (r) {
    const item = { id: cleanVal(r[0]), at: stampStr_(r[1]).slice(0, 16), studentId: cleanVal(r[2]), oldName: cleanVal(r[3]), newName: cleanVal(r[4]), by: cleanVal(r[5]), reason: cleanVal(r[7]), status: cleanVal(r[8]) };
    if (cleanVal(r[6]).toLowerCase() === user.email && item.status === DR_PENDING) out.myNameSuggestions.push({ id: item.id, studentId: item.studentId, status: item.status });
    if (user.tier === "T4") {
      if (item.status === DR_PENDING) out.nameInbox.push(item);
      if (item.at >= feedCut && item.by !== user.name) feed.push({ type: "name_suggestion", at: item.at, text: item.by + " اقترح تغيير اسم «" + item.oldName + "» إلى «" + item.newName + "»" + (item.status === DR_PENDING ? "" : " — " + item.status) });
    }
  });

  feed.sort(function (a, b) { return a.at < b.at ? 1 : a.at > b.at ? -1 : 0; });
  out.feed = feed.slice(0, FEED_MAX);
  const seen = getProp_(seenKey_(user.email)) || "";
  out.feedSeen = seen;
  out.feedUnread = out.feed.filter(function (f) { return f.at > seen; }).length;
  return out;
}

/* ============================ PHASE 2: COURSE REQUESTS ============================ */

const RQ_ST = { NEW: "جديد", T3: "عند مسؤول", ASSIGNED: "مُسنَد", CALLED: "تم الاتصال الأول", PROGRESS: "قيد المتابعة", NOANS: "لم يردّ", DONE: "تم الإدماج", CANCEL: "ملغى" };
const RQ_ESSENTIALS = ["لم يأخذ دروساً من قبل", "أخذ ولكن لم يكمل الضروري", "أخذ الضروري"];
const RQ_COURSE_TYPES = ["عن بعد", "في المقرّ", "في بيته"];
const RQ_LEVELS = ["1", "2", "3", "4"];
const RQ_INVITED = ["نعم", "لا"];
const RQ_ALERT_DAYS = 2;            // an open request with no update for this many days raises an alert
const RQ_SHEET = { name: "طلبات الدروس", headers: ["معرف الطلب", "تاريخ وصول الطلب", "أنشأه", "بريد المنشئ", "الاسم واللقب", "الهاتف", "البلد", "الحيّ", "المستوى", "الفئة العمرية", "هل أكمل الضروري", "نوع الدرس المطلوب", "الأوقات المقترحة", "دُعي للدرس العام", "الوسيط", "معطيات أخرى", "الحالة", "المسؤول (T3)", "بريد المسؤول", "المكلّف بالمتابعة", "بريد المكلّف", "تاريخ أول إسناد", "تاريخ أول اتصال", "آخر تحديث", "تاريخ الإدماج", "رمز الدرس", "معرف الطالب", "الولاية"] };
const RQ_EVENTS = { name: "سجل الطلبات", headers: ["معرف الطلب", "الوقت", "المنفّذ", "بريده", "نوع الحدث", "من حالة", "إلى حالة", "النص", "المكلّف"] };
const RC = { id: 0, createdAt: 1, createdBy: 2, createdByEmail: 3, name: 4, phone: 5, country: 6, city: 7, level: 8, age: 9, essentials: 10, courseType: 11, times: 12, invited: 13, intermediary: 14, other: 15, status: 16, t3: 17, t3Email: 18, assignee: 19, assigneeEmail: 20, firstAssignedAt: 21, firstCallAt: 22, lastUpdate: 23, doneAt: 24, courseCode: 25, studentId: 26, state: 27 };
const RQ_WIDTH = 28;

function rqIsOpen_(st) { return st !== RQ_ST.DONE && st !== RQ_ST.CANCEL; }
function todayISO_() { return fmtDate_(new Date(), "yyyy-MM-dd"); }
function daysBetween_(a, b) {
  const pa = String(a).slice(0, 10).split("-").map(Number), pb = String(b).slice(0, 10).split("-").map(Number);
  if (pa.length < 3 || pb.length < 3 || isNaN(pa[0]) || isNaN(pb[0])) return null;
  return Math.round((Date.UTC(pb[0], pb[1] - 1, pb[2]) - Date.UTC(pa[0], pa[1] - 1, pa[2])) / 86400000);
}

function rqObj_(r, rowNum) {
  const g = function (i) { return cleanVal(r[i]); };
  return {
    row: rowNum, id: g(RC.id), createdAt: stampStr_(r[RC.createdAt]), createdBy: g(RC.createdBy), createdByEmail: g(RC.createdByEmail).toLowerCase(),
    name: g(RC.name), phone: g(RC.phone), country: g(RC.country), state: g(RC.state), city: g(RC.city), level: g(RC.level), age: g(RC.age), essentials: g(RC.essentials),
    courseType: g(RC.courseType), times: g(RC.times), invited: g(RC.invited), intermediary: g(RC.intermediary), other: g(RC.other),
    status: g(RC.status), t3: g(RC.t3), t3Email: g(RC.t3Email).toLowerCase(), assignee: g(RC.assignee), assigneeEmail: g(RC.assigneeEmail).toLowerCase(),
    firstAssignedAt: stampStr_(r[RC.firstAssignedAt]), firstCallAt: stampStr_(r[RC.firstCallAt]), lastUpdate: stampStr_(r[RC.lastUpdate]),
    doneAt: stampStr_(r[RC.doneAt]), courseCode: g(RC.courseCode), studentId: g(RC.studentId)
  };
}

/** The sheet gained a last column "الولاية": add it (grid + header) to sheets created before. */
function rqSheet_(ss, create) {
  const sh = p1Sheet_(ss, RQ_SHEET, create);
  if (sh) {
    // v58: the last used column comes from the cached copy; the grid size is asked only when it may be too small
    if (typeof sh.getMaxColumns === "function" && sh.getLastColumn() < RQ_WIDTH && sh.getMaxColumns() < RQ_WIDTH) sh.insertColumnsAfter(sh.getMaxColumns(), RQ_WIDTH - sh.getMaxColumns());
    const h = sh.getRange(1, 1, 1, RQ_WIDTH).getValues()[0];
    if (!cleanVal(h[RC.state])) sh.getRange(1, RC.state + 1).setValue("الولاية");
    if (cleanVal(h[RC.city]) === "المدينة أو الحي") sh.getRange(1, RC.city + 1).setValue("الحيّ");
  }
  return sh;
}

function rqLoad_(ss) {
  const sh = rqSheet_(ss, false);
  const out = [];
  p1Rows_(sh, RQ_WIDTH).forEach(function (r, i) { if (cleanVal(r[RC.id])) out.push(rqObj_(r, i + 2)); });
  return { sheet: sh, list: out };
}

function rqSave_(sh, o) {
  sh.getRange(o.row, RC.status + 1, 1, RQ_WIDTH - RC.status).setValues([[
    o.status, safeCell_(o.t3), o.t3Email, safeCell_(o.assignee), o.assigneeEmail, o.firstAssignedAt, o.firstCallAt, o.lastUpdate, o.doneAt, safeCell_(o.courseCode), o.studentId, safeCell_(o.state)
  ]]);
}

function rqEvent_(ss, reqId, user, type, from, to, text, target) {
  const sh = p1Sheet_(ss, RQ_EVENTS, true);
  sh.getRange(sh.getLastRow() + 1, 1, 1, 9).setValues([[reqId, nowStamp_(), safeCell_(user.name), user.email, type, from || "", to || "", safeCell_(text || ""), safeCell_(target || "")]]);
}

function rqRoles_(o, user) {
  return { admin: user.tier === "T4", creator: o.createdByEmail === user.email, t3: o.t3Email === user.email, assignee: o.assigneeEmail === user.email };
}

function rqCan_(o, user) {
  const ro = rqRoles_(o, user), open = rqIsOpen_(o.status), hasAssignee = !!o.assigneeEmail;
  const handler = ro.admin || ro.t3 || ro.assignee;
  return {
    assign: open && (ro.admin || (user.tier === "T3" && (ro.t3 || ro.assignee))),
    status: open && handler && hasAssignee,
    cancel: open && handler,
    place: open && hasAssignee && (ro.assignee || ro.admin),
    note: open && handler
  };
}

function rqVisible_(o, user) { const ro = rqRoles_(o, user); return ro.admin || ro.creator || ro.t3 || ro.assignee; }

function rqAssignees_(user, staff, scope) {
  const out = [];
  if (user.tier === "T4") {
    staff.forEach(function (s) { if (s.tier === "T3" && s.email) out.push(s); });
  } else if (user.tier === "T3") {
    const seen = {};
    scope.supervisees.forEach(function (s) { if ((s.tier === "T1" || s.tier === "T2") && s.email && !seen[s.email]) { seen[s.email] = true; out.push(s); } });
    staff.forEach(function (s) { if (s.tier === "T3" && s.email && !seen[s.email]) { seen[s.email] = true; out.push(s); } });
  }
  return out;
}

function rqView_(o, user, today) {
  const open = rqIsOpen_(o.status);
  const endDay = o.status === RQ_ST.DONE ? o.doneAt : (open ? today : o.lastUpdate);
  const daysOpen = daysBetween_(o.createdAt, endDay);
  const since = daysBetween_(o.lastUpdate || o.createdAt, today);
  const ro = rqRoles_(o, user);
  const needsAction = open && ((ro.admin && o.status === RQ_ST.NEW) || (ro.t3 && user.tier === "T3" && o.status === RQ_ST.T3) ||
    (ro.assignee && (o.status === RQ_ST.ASSIGNED || o.status === RQ_ST.CALLED || o.status === RQ_ST.PROGRESS || o.status === RQ_ST.NOANS)));
  return {
    id: o.id, createdAt: o.createdAt, createdBy: o.createdBy, name: o.name, phone: o.phone, country: o.country, state: o.state, city: o.city, level: o.level, age: o.age,
    essentials: o.essentials, courseType: o.courseType, times: o.times, invited: o.invited, intermediary: o.intermediary, other: o.other,
    status: o.status, t3: o.t3, assignee: o.assignee, firstAssignedAt: o.firstAssignedAt, firstCallAt: o.firstCallAt,
    lastUpdate: o.lastUpdate, doneAt: o.doneAt, courseCode: o.courseCode, studentId: o.studentId,
    daysOpen: daysOpen, daysSinceUpdate: since, open: open, overdue: open && since !== null && since >= RQ_ALERT_DAYS,
    needsAction: needsAction, can: rqCan_(o, user)
  };
}

function rqStats_(views) {
  const by = {}, avg = function (a) { return a.length ? Math.round(a.reduce(function (x, y) { return x + y; }, 0) / a.length * 10) / 10 : null; };
  Object.keys(RQ_ST).forEach(function (k) { by[RQ_ST[k]] = 0; });
  const toAssign = [], toCall = [], toDone = [];
  let open = 0, overdue = 0, oldest = 0, doneMonth = 0;
  const month = todayISO_().slice(0, 7);
  views.forEach(function (v) {
    by[v.status] = (by[v.status] || 0) + 1;
    if (v.open) { open++; if (v.overdue) overdue++; if (v.daysOpen !== null && v.daysOpen > oldest) oldest = v.daysOpen; }
    const a = daysBetween_(v.createdAt, v.firstAssignedAt); if (v.firstAssignedAt && a !== null) toAssign.push(a);
    const c = daysBetween_(v.createdAt, v.firstCallAt); if (v.firstCallAt && c !== null) toCall.push(c);
    if (v.status === RQ_ST.DONE && v.daysOpen !== null) { toDone.push(v.daysOpen); if (String(v.doneAt).slice(0, 7) === month) doneMonth++; }
  });
  return { byStatus: by, total: views.length, open: open, overdue: overdue, unassigned: by[RQ_ST.NEW] || 0, oldestOpenDays: oldest,
    avgDaysToAssign: avg(toAssign), avgDaysToFirstCall: avg(toCall), avgDaysToDone: avg(toDone), doneCount: toDone.length, doneThisMonth: doneMonth, alertDays: RQ_ALERT_DAYS };
}

function buildPhase2Data_(ctx, scope) {
  const user = ctx.user, today = todayISO_();
  const loaded = rqLoad_(ctx.ss);
  const mine = loaded.list.filter(function (o) { return rqVisible_(o, user); });
  const views = mine.map(function (o) { return rqView_(o, user, today); });
  const keep = {};
  views.forEach(function (v) { if (v.open || (v.doneAt && daysBetween_(v.doneAt, today) <= 60) || daysBetween_(v.lastUpdate, today) <= 60) keep[v.id] = true; });
  const events = {};
  let n = 0;
  p1Rows_(p1Sheet_(ctx.ss, RQ_EVENTS, false), 9).forEach(function (r) {
    const id = cleanVal(r[0]);
    if (!keep[id] || n >= 2500) return;
    (events[id] = events[id] || []).push({ at: stampStr_(r[1]).slice(0, 16), by: cleanVal(r[2]), type: cleanVal(r[4]), from: cleanVal(r[5]), to: cleanVal(r[6]), text: cleanVal(r[7]), target: cleanVal(r[8]) });
    n++;
  });
  const out = {
    requests: views, requestEvents: events,
    requestAssignees: rqAssignees_(user, ctx.staff, scope).map(function (s) { return { email: s.email, name: s.name, tier: s.tier }; }),
    requestAlerts: mine.filter(function (o, i) {
      if (!views[i].overdue) return false;
      return user.tier === "T4" || o.assigneeEmail === user.email || (user.tier === "T3" && o.t3Email === user.email);
    }).length,
    requestActions: views.filter(function (v) { return v.needsAction; }).length,
    requestEnums: { statuses: RQ_ST, essentials: RQ_ESSENTIALS, courseTypes: RQ_COURSE_TYPES, levels: RQ_LEVELS, invited: RQ_INVITED, ageGroups: CFG.AGE_GROUPS.slice(), alertDays: RQ_ALERT_DAYS }
  };
  if (user.tier === "T4") out.requestStats = rqStats_(views);   // averages: the director only
  // name -> tier, only for the people appearing in the requests this user can see (so every name can carry its tag)
  const byName = {};
  ctx.staff.forEach(function (st) { byName[st.normName] = st.tier; });
  const tiers = {};
  views.forEach(function (v) { [v.createdBy, v.t3, v.assignee].forEach(function (nm) { const t = nm && byName[normName(nm)]; if (t) tiers[nm] = t; }); });
  out.peopleTiers = tiers;
  return out;
}

function rqFind_(ss, id, user) {
  const loaded = rqLoad_(ss);
  const o = loaded.list.filter(function (x) { return x.id === id; })[0];
  if (!o || !rqVisible_(o, user)) fail_("NOT_FOUND", "الطلب غير موجود.");
  return { sheet: loaded.sheet, o: o, all: loaded.list };
}

function readRequestFields_(p) {
  const f = {};
  f.name = text_(p.name, 80, "الاسم واللقب", true);
  if (f.name.length < 2) fail_("BAD_INPUT", "الاسم واللقب قصير جداً.");
  f.phone = cleanVal(p.phone);
  if (!f.phone) fail_("BAD_INPUT", "رقم الهاتف مطلوب.");
  if (!/^[0-9+\s]{6,20}$/.test(f.phone)) fail_("BAD_INPUT", "رقم الهاتف غير صالح.");
  f.country = text_(p.country, 40, "البلد", false) || "تونس";
  f.state = text_(p.state, 40, "الولاية", true);
  f.city = text_(p.city, 60, "الحيّ", true);
  f.level = enum_(cleanVal(p.level) || "1", RQ_LEVELS, "المستوى");
  f.age = text_(normAge_(p.age), 10, "الفئة العمرية", true);
  if (CFG.AGE_GROUPS.indexOf(f.age) === -1) fail_("BAD_INPUT", "الفئة العمرية غير صالحة.");
  f.essentials = enum_(cleanVal(p.essentials), RQ_ESSENTIALS, "هل أكمل الضروري");
  f.courseType = enum_(cleanVal(p.courseType), RQ_COURSE_TYPES, "نوع الدرس");
  f.times = text_(p.times, 200, "الأوقات المقترحة", false);
  f.invited = enum_(cleanVal(p.invited), RQ_INVITED, "الدعوة للدرس العام");
  f.intermediary = text_(p.intermediary, 80, "الوسيط", false);
  f.other = text_(p.other, 300, "معطيات أخرى", false);
  return f;
}

function digits_(s) { return String(s).replace(/\D/g, "").replace(/^(00)?216/, ""); }

function actionCreateRequest_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const f = readRequestFields_(p);
    areaEnforce_(ctx.ss, f, "city", f.country);   // v62: a place of «المعتمديات» (abroad: free)
    const loaded = rqLoad_(ctx.ss);
    if (!p.force) {
      const dg = digits_(f.phone);
      const dup = loaded.list.filter(function (o) { return rqIsOpen_(o.status) && dg && digits_(o.phone) === dg; })[0];
      if (dup) fail_("DUPLICATE", "يوجد طلب مفتوح بنفس رقم الهاتف (" + dup.id + "). إن كان طلباً مختلفاً فأكّد الإضافة.");
    }
    let max = 0;
    loaded.list.forEach(function (o) { const m = /^RQ-(\d+)$/.exec(o.id); if (m) max = Math.max(max, parseInt(m[1], 10)); });
    const id = __genId("RQ", "RQ-" + ("0000" + (max + 1)).slice(-4));
    const now = nowStamp_();
    const sh = rqSheet_(ctx.ss, true);
    const row = new Array(RQ_WIDTH).fill("");
    row[RC.id] = id; row[RC.createdAt] = now; row[RC.createdBy] = safeCell_(user.name); row[RC.createdByEmail] = user.email;
    row[RC.name] = safeCell_(f.name); row[RC.phone] = safeCell_(f.phone); row[RC.country] = safeCell_(f.country); row[RC.state] = safeCell_(f.state); row[RC.city] = safeCell_(f.city);
    row[RC.level] = f.level; row[RC.age] = f.age; row[RC.essentials] = f.essentials; row[RC.courseType] = f.courseType;
    row[RC.times] = safeCell_(f.times); row[RC.invited] = f.invited; row[RC.intermediary] = safeCell_(f.intermediary); row[RC.other] = safeCell_(f.other);
    row[RC.status] = RQ_ST.NEW; row[RC.lastUpdate] = now;
    const target = sh.getLastRow() + 1;
    sh.getRange(target, 1, 1, RQ_WIDTH).setValues([row]);
    rqEvent_(ctx.ss, id, user, "إنشاء", "", RQ_ST.NEW, "", "");
    recordLog(ctx.ss, user.name, user.email, "طلب التحاق بدرس", "الطلب: " + id);
    const w = loadWorld_(ctx, true), key = normName(f.name);
    const existing = w.students.some(function (s) { return s.normName === key; });
    const o = rqObj_(row, target);
    return { success: true, message: "تم إرسال الطلب إلى الإدارة", request: rqView_(o, user, todayISO_()), warningExistingStudent: existing };
  });
}

function actionAssignRequest_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const id = text_(p.requestId, 20, "معرف الطلب", true);
    const found = rqFind_(ctx.ss, id, user), o = found.o;
    if (!rqCan_(o, user).assign) fail_("FORBIDDEN", "لا تملك صلاحية إسناد هذا الطلب.");
    const scope = buildScope_(user, ctx.staff, loadCourses_(readTable_(ctx.ss, "courses", true), ctx.staff));
    const email = cleanVal(p.toEmail).toLowerCase();
    const target = rqAssignees_(user, ctx.staff, scope).filter(function (s) { return s.email === email; })[0];
    if (!target) fail_("BAD_INPUT", user.tier === "T4" ? "يُسند المدير الطلب إلى مسؤول من فئة T3 فقط." : "الشخص المختار غير متاح للإسناد.");
    const note = text_(p.note, 200, "ملاحظة", false);
    const from = o.status, now = nowStamp_();
    if (user.tier === "T4") {
      o.t3 = target.name; o.t3Email = target.email; o.assignee = ""; o.assigneeEmail = ""; o.status = RQ_ST.T3;
    } else {
      o.assignee = target.name; o.assigneeEmail = target.email; o.status = RQ_ST.ASSIGNED;
      if (!o.t3Email) { o.t3 = user.name; o.t3Email = user.email; }
    }
    if (!o.firstAssignedAt) o.firstAssignedAt = now;
    o.lastUpdate = now;
    rqSave_(found.sheet, o);
    rqEvent_(ctx.ss, id, user, "إسناد", from, o.status, note, target.name);
    recordLog(ctx.ss, user.name, user.email, "إسناد طلب", "الطلب: " + id + " | إلى: " + target.name);
    return { success: true, message: "تم الإسناد إلى " + target.name, request: rqView_(o, user, todayISO_()) };
  });
}

function actionSetRequestStatus_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const id = text_(p.requestId, 20, "معرف الطلب", true);
    const found = rqFind_(ctx.ss, id, user), o = found.o;
    const can = rqCan_(o, user);
    const target = enum_(cleanVal(p.status), [RQ_ST.CALLED, RQ_ST.PROGRESS, RQ_ST.NOANS, RQ_ST.CANCEL], "الحالة");
    if (target === RQ_ST.CANCEL ? !can.cancel : !can.status) {
      fail_(rqIsOpen_(o.status) && !o.assigneeEmail && target !== RQ_ST.CANCEL ? "CONFLICT" : "FORBIDDEN",
        rqIsOpen_(o.status) && !o.assigneeEmail && target !== RQ_ST.CANCEL ? "يجب إسناد الطلب إلى مكلّف بالمتابعة أولاً." : "لا تملك صلاحية تغيير حالة هذا الطلب.");
    }
    const needNote = target === RQ_ST.CALLED || target === RQ_ST.CANCEL;
    const note = text_(p.note, 300, "الملاحظة", needNote);
    const from = o.status, now = nowStamp_();
    o.status = target; o.lastUpdate = now;
    if (target === RQ_ST.CALLED && !o.firstCallAt) o.firstCallAt = now;
    rqSave_(found.sheet, o);
    rqEvent_(ctx.ss, id, user, target === RQ_ST.CANCEL ? "إلغاء" : "تغيير الحالة", from, target, note, "");
    recordLog(ctx.ss, user.name, user.email, "حالة طلب", "الطلب: " + id + " | " + from + " ← " + target);
    return { success: true, message: "تم تحديث الحالة", request: rqView_(o, user, todayISO_()) };
  });
}

function actionAddRequestNote_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const id = text_(p.requestId, 20, "معرف الطلب", true);
    const found = rqFind_(ctx.ss, id, user), o = found.o;
    if (!rqCan_(o, user).note) fail_("FORBIDDEN", "لا تملك صلاحية إضافة ملاحظة على هذا الطلب.");
    const note = text_(p.note, 300, "الملاحظة", true);
    o.lastUpdate = nowStamp_();
    rqSave_(found.sheet, o);
    rqEvent_(ctx.ss, id, user, "ملاحظة", o.status, o.status, note, "");
    return { success: true, message: "تمت إضافة الملاحظة", request: rqView_(o, user, todayISO_()) };
  });
}

/** Phone -> comparable key: digits only, without 00 / country code 216; last 8 digits. */
function phoneKey_(v) {
  let d = String(v || "").replace(/\D+/g, "");
  if (d.indexOf("00") === 0) d = d.slice(2);
  if (d.length > 8 && d.indexOf("216") === 0) d = d.slice(3);
  return d.length >= 6 ? d.slice(-8) : "";
}

/**
 * Candidate "same person" matches. Signals: same phone (strongest, but families share phones),
 * same normalized name, similar name (>= 2 shared name parts). City never vetoes: it is only reported.
 * The result is a SUGGESTION for a human; nothing is merged automatically.
 */
function findStudentMatches_(students, q) {
  const pk = phoneKey_(q.phone), nk = normName(q.name || ""), ck = normName(q.city || "");
  const qt = nk.split(/\s+/).filter(Boolean);
  const out = [];
  students.forEach(function (s) {
    const reasons = [];
    if (pk && phoneKey_(s.phone) === pk) reasons.push("phone");
    if (nk && s.normName === nk) reasons.push("name");
    else if (qt.length >= 2) {
      const st = s.normName.split(/\s+/).filter(Boolean);
      const shared = qt.filter(function (t) { return st.indexOf(t) !== -1; }).length;
      if (shared >= 2) reasons.push("similar");
    }
    if (!reasons.length) return;
    const score = (reasons.indexOf("phone") !== -1 ? 4 : 0) + (reasons.indexOf("name") !== -1 ? 3 : 0) + (reasons.indexOf("similar") !== -1 ? 1 : 0);
    out.push({ st: s, reasons: reasons, score: score, sameCity: !!(ck && normName(s.city) === ck), cityDiffers: !!(ck && s.city && normName(s.city) !== ck) });
  });
  out.sort(function (a, b) { return b.score - a.score; });
  return out.slice(0, 5);
}

function maskedStudent_(st, m) {
  const o = { id: st.id, name: st.name, city: st.city, level: st.level, ageGroup: st.ageGroup, phoneTail: st.phone ? String(st.phone).slice(-3) : "", courseCodes: st.codesStr, unassigned: st.unassigned };
  if (m) { o.reasons = m.reasons; o.sameCity = m.sameCity; o.cityDiffers = m.cityDiffers; }
  return o;
}

function rebuildCodes_(st, courseCode, courseNorm) {
  const raw = String(st.codesStr || "").split(/[,،;\r\n\/]+/).map(function (s) { return s.trim(); }).filter(Boolean);
  const out = [], seen = {};
  raw.forEach(function (tok) { const n = normCode(tok); if (isUnassignedNorm(n) || seen[n]) return; seen[n] = true; out.push(tok); });
  if (!seen[courseNorm]) out.push(courseCode);
  return out.join(", ");
}

function actionPlaceRequest_(ctx, p) {
  return withLock_(function () {
    const user = ctx.user;
    const id = text_(p.requestId, 20, "معرف الطلب", true);
    const found = rqFind_(ctx.ss, id, user), o = found.o;
    if (!rqCan_(o, user).place) fail_("FORBIDDEN", "لا تملك صلاحية إدماج الطالب لهذا الطلب.");
    const w = loadWorld_(ctx, true);
    const course = findCourse_(w, p.courseCode);
    if (!course) fail_("NOT_FOUND", "الدرس غير موجود.");
    const isOwn = !!(course.owner && course.owner.row === user.row);
    if (!(isOwn || user.tier === "T4")) fail_("FORBIDDEN", "يمكنك إدماج الطالب في دروسك فقط.");
    if (isUnassignedNorm(course.normCode)) fail_("BAD_INPUT", "اختر درساً فعلياً.");

    const matches = findStudentMatches_(w.students, { name: o.name, phone: o.phone, city: o.city });
    const existingId = cleanVal(p.existingStudentId);
    let studentId, enrolledExisting = false, codes = "";
    if (existingId) {
      const st = w.students.filter(function (s) { return s.id === existingId; })[0];
      if (!st) fail_("NOT_FOUND", "الطالب المختار لم يعد موجوداً.");
      codes = rebuildCodes_(st, course.code, course.normCode);
      w.studentTbl.sheet.getRange(st.row, w.studentTbl.idx.codes + 1).setValue(codes);
      studentId = st.id; enrolledExisting = true;
    } else {
      if (matches.length && !p.force) fail_("DUPLICATE", "يوجد طالب مسجل بنفس الاسم. اختر إن كان هو نفسه أو شخصاً آخر.", { matches: matches.map(function (m) { return maskedStudent_(m.st, m); }) });
      const f = {
        name: o.name, category: /نساء/.test(course.category || "") ? "نساء" : "رجال", ageGroup: o.age, level: o.level,
        city: o.city, location: course.venue || "", phone: o.phone, completedBooks: ""
      };
      studentId = insertStudentRow_(ctx, w, f, course.code);
      codes = course.code;
    }
    const from = o.status, now = nowStamp_();
    o.status = RQ_ST.DONE; o.doneAt = now; o.lastUpdate = now; o.courseCode = course.code; o.studentId = studentId;
    rqSave_(found.sheet, o);
    rqEvent_(ctx.ss, id, user, "إدماج", from, RQ_ST.DONE, (enrolledExisting ? "أضيف إلى طالب موجود " : "طالب جديد ") + studentId + " في " + course.code, "");
    recordLog(ctx.ss, user.name, user.email, "إدماج طالب من طلب", "الطلب: " + id + " | الطالب: " + studentId + " | الدرس: " + course.code);
    return { success: true, message: "تم إدماج الطالب في الدرس", studentId: studentId, enrolledExisting: enrolledExisting, courseCodes: codes, request: rqView_(o, user, todayISO_()) };
  });
}

/* ============== DEPARTMENT 2: الأنشطة (نظام الصفوف) ==============
 * Separate sheets and actions. A member's صف is never stored on his row: it is COMPUTED
 *   filter "teacher": the صف of each of his teachers (a member may appear in several)
 *   filter "geo"    : the صف whose area contains his الحيّ / المدينة (exactly one)
 * Members of level 7 (دروس الصف) are pinned to the صف of that course's teacher under both filters.
 * Nothing here writes to the education sheets.
 */
/** Filter 2 (by location) is paused: set to true once «مناطق الصفوف» is filled. Filter 1 (by teacher) is always on. */
let ACT_GEO_ENABLED = false;
const ACT_ACTIONS = { actInit: true, actSetDefaultFilter: true, actContribInit: true, actSetDeclared: true, actSetPaid: true, actSetDeclaredMany: true, actSetPaidMany: true, actClassAttSave: true, majlisInit: true, majlisSave: true, majlisDone: true, majlisSearch: true, actClassInit: true, pubLoad: true, pubSearch: true, pubMark: true, pubMarkMany: true, pubNew: true, pubCount: true, actAreaLearn: true };
const ACT = {
  CLASSES: { name: "الصفوف", headers: ["مفتاح الصف", "اسم الصف", "الصنف", "الفرع", "المجموعة"] },
  TEACHERS: { name: "صفوف المدرسين", headers: ["المدرس", "مفتاح الصف", "الصفة"] },
  GEO: { name: "مناطق الصفوف", headers: ["الحيّ / المدينة", "مفتاح الصف"] },
  SETTINGS: { name: "إعدادات الأنشطة", headers: ["المفتاح", "القيمة"] },
  DECLARED: { name: "المساهمة المعلنة", headers: ["معرّف العضو", "الاسم", "المساهمة المعلنة", "عدّلها", "التاريخ"] },
  MAJLIS: { name: "طلبات مجالس الذكر", headers: ["رقم الطلب", "تاريخ المجلس", "المقر", "صاحب الطلب (الاسم واللقب)", "الهاتف", "الحي / المدينة", "التبرع (د.ت)", "معرّفات المشاركين", "المشاركون", "أنشأه", "البريد", "تاريخ الإنشاء", "آخر تعديل"] },
  PAID: { name: "المساهمة المدفوعة", headers: ["معرّف العضو", "الاسم", "الشهر", "المساهمة المدفوعة", "سجّلها", "التاريخ"] },
  CLASSATT: { name: "حضور الصف", headers: ["التاريخ", "معرّف الفرد", "الاسم", "الحضور", "سجّله", "وقت التسجيل"] },
  AREAS: { name: "المعتمديات", headers: ["المنطقة", "النوع", "المعتمدية", "الولاية", "أسماء أخرى", "صف الرجال", "صف النساء", "ملاحظة"] }
};
const ACT_FILTER_KEY = "الفلتر الافتراضي";
const ACT_CLASS_SEED = [
  ["من12|ر", "منفلوري 1و2", "رجال", "منفلوري"], ["من3|ر", "منفلوري 3", "رجال", "منفلوري"], ["من4|ر", "منفلوري 4", "رجال", "منفلوري"],
  ["من1|ن", "منفلوري 1", "نساء", "منفلوري"], ["من2|ن", "منفلوري 2", "نساء", "منفلوري"], ["من3|ن", "منفلوري 3", "نساء", "منفلوري"],
  ["أر|ر", "أريانة", "رجال", "أريانة"], ["أر|ن", "أريانة", "نساء", "أريانة"],
  ["مر|ر", "المرسى", "رجال", "المرسى"], ["مر|ن", "المرسى", "نساء", "المرسى"],
  ["مح|ن", "المحمدية", "نساء", "المحمدية"],
  ["نا|ر", "نابل", "رجال", "نابل"], ["نا1|ن", "نابل 1", "نساء", "نابل"], ["نا2|ن", "نابل 2", "نساء", "نابل"]
];

function actRead_(ss, def) {
  const sh = ss.getSheetByName(def.name);
  if (!sh || sh.getLastRow() < 2) return { sheet: sh, rows: [] };
  const w = Math.min(def.headers.length, sh.getLastColumn());
  return { sheet: sh, rows: sh.getRange(2, 1, sh.getLastRow() - 1, w).getValues() };
}


/* ============== v61/v62: الصف حسب المنطقة ==============
 * «المعتمديات» lists every place: معتمدية, عمادة, حي (and a few special rows: other governorates, countries).
 * A row's صف is its own «صف الرجال / صف النساء», or, when empty, the one of its «المعتمدية» row (inheritance).
 * A person's «الحيّ / المدينة» is matched every time the app reads him (nothing stored), so a new person or an
 * edited area lands in the right صف at once. No match / no صف → the usual rule (المقر, then the teacher).
 * Level 7 (دروس الصف) is never moved. v62: new entries must be a place of the list (server-checked).
 */
