/** One-off: rewrites the old age label "36+" to "60+" in the students sheet (only those cells). */
function fixAgeGroups() { return withCacheBump_(function () { return fixAgeGroupsImpl_(); }); }
function fixAgeGroupsImpl_() {
  const ss = openSS_();
  const tbl = readTable_(ss, "students");
  const col = tbl.idx.ageGroup + 1;
  let n = 0;
  for (let i = 1; i < tbl.values.length; i++) {
    const raw = cleanVal(tbl.values[i][tbl.idx.ageGroup]);
    if (raw && normAge_(raw) === "60+" && raw !== "60+") { tbl.sheet.getRange(i + 1, col).setValue("60+"); n++; }
  }
  Logger.log("fixAgeGroups: " + n + " cellule(s) corrigée(s)");
  return n;
}

